BEGIN;

-- Resep ID: 2 - Soto Ayam Kampung
UPDATE public.recipes SET instructions = ARRAY['Rebus ayam kampung dalam air mendidih bersama serai dan daun jeruk hingga empuk. Angkat ayam, tiriskan, dan suwir-suwir dagingnya. Jangan buang air kaldu rebusannya.', 'Haluskan bawang merah, bawang putih, kunyit, jahe, kemiri, ketumbar, dan merica.', 'Tumis bumbu halus hingga harum dan matang, lalu masukkan ke dalam panci berisi kaldu ayam hangat.', 'Didihkan kuah soto dengan api kecil agar bumbu meresap sempurna. Tambahkan garam dan gula secukupnya.', 'Seduh soun dan tauge dengan air panas, lalu iris kol tipis-tipis.', 'Tata soun, kol, tauge, suwiran ayam, dan irisan telur rebus di dalam mangkok.', 'Siram dengan kuah soto panas. Sajikan dengan bawang goreng, daun seledri, koya, dan jeruk nipis.']::text[] WHERE id = 2;

-- Resep ID: 8 - Ayam Goreng Bawang Khas Batam
UPDATE public.recipes SET instructions = ARRAY['Cuci ayam hingga bersih, kemudian tiriskan. Masukkan bumbu halus, garam, kaldu jamur, tepung maizena, dan telur. Aduk hingga tercampur rata.', 'Diamkan kurang lebih 30 menit di dalam kulkas agar bumbu meresap.', 'Panaskan minyak goreng, kemudian goreng bawang putih hingga kuning dan garing. Tiriskan.', 'Goreng ayam hingga cokelat keemasan dan matang merata. Goreng secara bertahap, jangan sekaligus. Angkat dan tiriskan.', 'Ayam goreng bawang siap disajikan.']::text[] WHERE id = 8;

-- Resep ID: 9 - Ayam Goreng Kecap
UPDATE public.recipes SET instructions = ARRAY['Lumuri ayam dengan air jeruk nipis dan garam, remas-remas, lalu bilas bersih. Ungkep ayam dengan garam dan merica. Bisa juga langsung digoreng, tetapi potong ayam agak kecil.', 'Setelah diungkep, goreng ayam hingga sedikit kecokelatan, angkat.', 'Panaskan secukupnya minyak, tumis bawang putih dan jahe, masukkan bawang bombay, tumis hingga harum. Masukkan cabai merah iris, ayam goreng, bubuhi gula, garam, merica, dan kecap, tuang air. Masak hingga kuah mengental, sesaat sebelum diangkat, masukkan daun bawang.', 'Angkat ayam dan sajikan.']::text[] WHERE id = 9;

-- Resep ID: 10 - Mie Ayam
UPDATE public.recipes SET instructions = ARRAY['Rebus mie telur hingga matang.', 'Rebus ayam hingga empuk dengan sedikit garam, kemudian potong kecil-kecil.', 'Tumis bawang bombai, bawang merah, dan bawang putih hingga harum.', 'Tambahkan jahe giling, daun salam, daun jeruk, dan serai.', 'Masukkan kecap manis, kecap asin, kecap Inggris, minyak wijen, dan saus tiram.', 'Masukkan ayam yang telah direbus, aduk rata.', 'Masukkan garam, penyedap rasa, dan merica bubuk sesuai selera.', 'Tambahkan sedikit air, masukkan potongan daun bawang. Masak hingga empuk.', 'Untuk kuah, siapkan air. Masukkan daun bawang, kaldu ayam, dan merica bubuk.', 'Tata mie ayam. Letakkan mie, topping ayam, dan siram dengan kuah.']::text[] WHERE id = 10;

-- Resep ID: 11 - Menu dinner trio tumis - pokcoy, ayam bawang putih, bawang merah
UPDATE public.recipes SET instructions = ARRAY['Cuci bersih pokcoy, lalu potong-potong. Panaskan wajan, tumis bawang putih hingga harum.', 'Masukkan pokcoy, kecap asin, air, gula, dan garam. Aduk rata selama sekitar 30 detik. Angkat dan sisihkan.', 'Campurkan semua bahan untuk ayam bawang putih, lalu marinasi di dalam kulkas selama beberapa jam (misalnya 8 jam).', 'Panaskan sedikit minyak, tumis ayam yang sudah dimarinasi hingga agak sedikit gosong. Angkat dan sisihkan.', 'Iris tipis bawang merah dan iris miring cabai.', 'Panaskan minyak agak banyak (sekitar 4-5 sendok makan), lalu tumis bawang merah dan cabai hingga harum. Masukkan gula, garam, dan kaldu jamur. Aduk rata dan cicipi rasa. Jika sudah pas, sisihkan.']::text[] WHERE id = 11;

-- Resep ID: 12 - Ayam Woku Manado
UPDATE public.recipes SET instructions = ARRAY['Rebus ayam dalam air mendidih selama 7 menit. Buang kotorannya, bilas, dan tiriskan.', 'Di wajan, tumis bumbu halus dengan minyak hingga harum. Masukkan daun jeruk, daun salam, daun pandan, dan serai. Tumis hingga matang.', 'Masukkan ayam, aduk rata. Tambahkan air, garam, gula, kaldu, dan tomat potong. Aduk rata dan koreksi rasa.', 'Masak hingga ayam matang empuk dan kuah menyusut. Matikan api, lalu masukkan daun kemangi. Aduk hingga daun layu.']::text[] WHERE id = 12;

-- Resep ID: 14 - Ayam Kecap Manis Cabai
UPDATE public.recipes SET instructions = ARRAY['Tumis bawang putih, cabai, dan merica bubuk hingga layu dan bawang putih agak kecokelatan.', 'Masukkan ayam, aduk hingga berubah warna.', 'Beri kecap manis, lalu tuang air. Bubuhi garam secukupnya, aduk rata, lalu tutup wajan hingga airnya sat dan bumbu meresap.', 'Sajikan lalu taburi dengan daun bawang.']::text[] WHERE id = 14;

-- Resep ID: 15 - Ayam Goreng Madu Pedes
UPDATE public.recipes SET instructions = ARRAY['Panaskan minyak di dalam kuali.', 'Sembari menunggu minyak panas, lumuri ayam dengan ketumbar, merica, garam, dan air lemon. Aduk rata, lalu masukkan tepung ayam goreng serbaguna dan tepung maizena. Aduk rata.', 'Setelah minyak panas, goreng ayam hingga matang dan tiriskan.', 'Sembari menggoreng ayam, buat sausnya. Panaskan sedikit minyak dan margarin. Setelah panas, tumis bawang putih hingga harum.', 'Setelah bawang putih harum, masukkan campuran saus. Aduk rata dan masak hingga mendidih.', 'Masukkan garam, merica, dan penyedap. Icip rasa, jika sudah pas, matikan api.', 'Masukkan ayam yang sudah digoreng ke dalam saus. Aduk rata dan siap disajikan.']::text[] WHERE id = 15;

-- Resep ID: 16 - Kalio Ati Ampela Ayam
UPDATE public.recipes SET instructions = ARRAY['Tumis bumbu halus dan bumbu cemplung hingga harum.', 'Masukkan potongan ati ampela ayam. Tunggu hingga ati ampela empuk.', 'Tambahkan santan kental, gula, garam, dan penyedap. Gunakan api kecil agar bumbu benar-benar meresap sempurna. Tunggu hingga santan menyusut dan mengental.', 'Koreksi rasanya, lalu angkat dan sajikan.']::text[] WHERE id = 16;

-- Resep ID: 17 - Ayam Katsu
UPDATE public.recipes SET instructions = ARRAY['Potong dan iris tipis dada ayam, lalu pukul-pukul hingga tipis melebar.', 'Lumuri ayam dengan bawang putih parut, kecap asin, garam, dan merica.', 'Balur ayam dengan tepung terigu, celupkan ke dalam kocokan putih telur, lalu lapisi dengan tepung panir sambil ditekan-tekan.', 'Biarkan sejenak hingga lapisan tepung agak kering.', 'Goreng dalam minyak panas dan banyak hingga berwarna kuning keemasan. Angkat dan tiriskan.']::text[] WHERE id = 17;

-- Resep ID: 18 - Bakso Ayam
UPDATE public.recipes SET instructions = ARRAY['Goreng bawang putih dan bawang merah hingga matang berwarna kuning keemasan, jangan sampai terlalu coklat mendekati gosong. Haluskan duo bawang goreng tersebut.', 'Masukkan semua bahan dan duo bawang halus ke dalam wadah. Aduk hingga bahan tercampur rata. Koreksi rasa dengan cara merebus sedikit adonan bakso, sesuaikan rasa sesuai selera.', 'Bulatkan bakso dengan 2 sendok makan. Rebus di air mendidih hingga bakso mengapung. Tiriskan.', 'Membuat kuah: Siapkan panci untuk bakso, tambahkan 2 sendok makan minyak sayur dan panaskan dengan api kompor sedang hingga minyak panas. Masukkan bawang putih dan tumis hingga harum, kecoklatan, dan keluar asap, lalu langsung tuangkan air. Masukkan semua bahan kuah bakso kecuali seledri. Rebus hingga mendidih dan koreksi rasa. Masukkan bakso secukupnya. Rebus kembali sebentar dan matikan api kompor. Sajikan hangat dengan suun, siomai, bawang goreng, dan daun seledri.']::text[] WHERE id = 18;

-- Resep ID: 19 - Roti Goreng Isi Ragout Ayam
UPDATE public.recipes SET instructions = ARRAY['Rebus sebentar kentang dan wortel. Tiriskan.', 'Panaskan margarin, tumis bawang bombay dan bawang putih hingga harum. Masukkan daging giling dan aduk hingga berubah warna dan bergerindil.', 'Masukkan tepung terigu dan aduk hingga matang. Tuang susu cair, lalu masukkan wortel, kentang, dan daun bawang. Tambahkan bumbu-bumbu dan aduk hingga mengental. Koreksi rasa. Setelah pas, dinginkan.', 'Buang pinggiran roti tawar jika menggunakan yang ada pinggirannya. Kukus sebentar hingga lemas.', 'Ambil selembar roti tawar, beri ragout di salah satu sisinya. Lipat dua dan tekan pinggirannya agar rapat.', 'Celupkan ke dalam telur kocok, lalu gulingkan di bread crumb. Goreng hingga keemasan.']::text[] WHERE id = 19;

-- Resep ID: 20 - Ayam Goreng Terasi ala resto
UPDATE public.recipes SET instructions = ARRAY['Campur bumbu marinasi ke dalam ayam, aduk rata, kemudian simpan di kulkas minimal 1 jam atau sampai bumbu meresap. Marinasi semalaman akan memberikan hasil yang lebih baik.', 'Siapkan bahan tepung.', 'Setelah 1 jam, keluarkan ayam, masukkan bahan tepung, dan campur rata.', 'Goreng dalam minyak panas sedang hingga matang merata, angkat dan tiriskan.', 'Ayam goreng terasi siap disajikan.']::text[] WHERE id = 20;

-- Resep ID: 21 - Nasi Tim Ayam
UPDATE public.recipes SET instructions = ARRAY['Tumis bawang merah, bawang putih, dan jahe hingga harum.', 'Masukkan ayam, aduk hingga berubah warna.', 'Masukkan gula, garam, merica, dan kecap manis.', 'Masak hingga ayam matang. Beri air secukupnya.', 'Masukkan larutan maizena. Aduk hingga mengental.', 'Olesi mangkuk stainless dengan minyak agar telur tidak menempel. Tata potongan telur di dasar mangkuk. Beri ayam di sekitarnya, lalu tuang kuah ayam.', 'Masukkan nasi lembek, lalu tekan-tekan hingga padat.', 'Kukus selama 15 menit.', 'Buat kuah: rebus air dengan gula, garam, dan merica bubuk. Beri minyak wijen. Masak hingga mendidih. Koreksi rasa.', 'Sajikan nasi tim dengan kuah. Dalam mangkuk kuah, beri irisan daun bawang.']::text[] WHERE id = 21;

-- Resep ID: 22 - Bubur Ayam Kuah Kuning
UPDATE public.recipes SET instructions = ARRAY['Cuci bersih ayam, didihkan air, masukkan ayam, rebus sampai matang. Angkat dan goreng. Setelah digoreng, suwir-suwir dagingnya. Air rebusan bisa digunakan untuk kuah kuning atau bubur.', 'Masukkan semua bahan bubur ke dalam rice cooker. Tekan tombol on, masak sampai matang.', 'Blender bawang putih, bawang merah, kemiri, dan kunyit. Tumis dengan sedikit minyak sampai harum, masukkan daun salam, daun jeruk, dan serai. Masukkan air, tunggu sampai mendidih, tambahkan santan dan garam. Aduk dan masak sampai matang.', 'Rebus telur puyuh dengan kecap dan bawang putih cincang sampai telur kecoklatan.', 'Rebus semua cabai, blender, dan masak sampai matang dengan sedikit minyak agar lebih tahan lama.', 'Sajikan dengan bahan pelengkap lainnya.', 'Siap dihidangkan.']::text[] WHERE id = 22;

-- Resep ID: 23 - Kung Pao Chicken
UPDATE public.recipes SET instructions = ARRAY['Aduk rata ayam dengan kecap asin dan maizena. Sisihkan.', 'Campur semua bahan saus. Sisihkan.', 'Potong-potong dan siapkan bahan lainnya.', 'Panaskan minyak, goreng ayam sampai matang kecoklatan. Angkat.', 'Tumis bawang putih, jahe, cabai, dan paprika.', 'Masukkan kembali ayam yang sudah digoreng dan saus. Aduk rata.', 'Masukkan daun bawang dan kacang. Aduk rata kembali, cek rasa, dan angkat.', 'Sajikan hangat.']::text[] WHERE id = 23;

-- Resep ID: 24 - Chicken Steak
UPDATE public.recipes SET instructions = ARRAY['Cuci paha ayam dan lap dengan tisu dapur. Kucuri dengan jeruk limau, garam, dan lada. Diamkan.', 'Campurkan kecap asin, gula pasir, air, dan arak masak menjadi satu dalam wadah.', 'Siapkan wajan, beri butter. Masukkan ayam dan tutup wajan selama 2 menit.', 'Balikkan ayam dan diamkan lagi selama 2 menit dengan menutup wajan.', 'Masukkan saus dan kecilkan api. Tutup selama 2 menit. Balikkan daging dan tambahkan sisa saus, lalu tutup lagi selama 2 menit. Matikan api.', 'Diamkan selama 5 menit, lalu angkat. Jika ada sisa saus, didihkan sampai kental dan tuang ke atas ayam.']::text[] WHERE id = 24;

-- Resep ID: 25 - Ayam Goreng Mentega
UPDATE public.recipes SET instructions = ARRAY['Lumuri ayam dengan garam dan merica, diamkan selama 15 menit.', 'Goreng ayam dalam minyak panas hingga kecokelatan, angkat dan tiriskan.', 'Lelehkan mentega, tumis bawang putih dan bawang bombay hingga harum.', 'Masukkan ayam goreng, tambahkan kecap manis, kecap asin, dan kecap inggris. Aduk hingga saus mengental. Angkat dan sajikan.']::text[] WHERE id = 25;

-- Resep ID: 26 - Soto Ayam Ambengan
UPDATE public.recipes SET instructions = ARRAY['Rebus dada ayam dengan sedikit garam, serai, dan daun jeruk. Masak dengan api kecil hingga setengah matang.', 'Sambil menunggu, siapkan bahan pelengkap.', 'Tumis bumbu halus hingga matang, lalu tambahkan ke dalam rebusan kaldu.', 'Bumbui dengan garam, gula, merica, kaldu bubuk, dan bawang putih goreng. Masak hingga daging empuk. Koreksi rasa.', 'Tiriskan daging, lalu goreng dan biarkan dingin. Setelah dingin, jangan disuwir, tetapi potong serong tipis.', 'Untuk penyajian, susun soon di atas mangkuk bersama ayam, telur rebus, taburan daun bawang, daun seledri, bawang goreng, dan poyah. Sajikan selagi panas dengan perkedel, sambal, jeruk nipis, poyah, nasi putih, dan kerupuk.']::text[] WHERE id = 26;

-- Resep ID: 27 - Nugget ayam wortel
UPDATE public.recipes SET instructions = ARRAY['Panaskan kukusan.', 'Haluskan ayam, bawang merah, dan bawang putih.', 'Taruh ayam yang sudah halus ke dalam baskom, kemudian campur dengan bahan lain: tepung terigu, tepung kanji, telur, garam, penyedap rasa, lada, dan wortel.', 'Setelah tercampur rata, kukus dalam wadah selama kurang lebih 30 menit.', 'Potong-potong setelah dingin, celupkan ke dalam telur kocok, kemudian gulingkan ke dalam tepung panir. Untuk hasil yang lebih bagus, simpan ke dalam freezer sekitar 1 jam sebelum digoreng.', 'Saat mengukus, tutup dengan serbet agar air tidak jatuh ke nugget yang dapat membuat teksturnya lembek.']::text[] WHERE id = 27;

-- Resep ID: 28 - Chilli Tuna Puff Kilat
UPDATE public.recipes SET instructions = ARRAY['Tumis chili tuna chunk dengan minyak bawang, lalu masukkan jagung pipil. Tambahkan gula, garam, dan merica atau lada hitam sesuai selera.', 'Terakhir, taburi chili flakes atau boncabe dan parsley cincang. Aduk rata, lalu sisihkan.', 'Potong puff pastry sesuai bentuk yang diinginkan. Isi dengan telur rebus dan tumisan tuna, lalu lipat. Pipihkan sisi-sisinya menggunakan ujung garpu agar tidak bocor.', 'Olesi permukaan puff dengan kuning telur. Semprotkan saus dan taburi parsley.', 'Panggang dengan suhu sekitar 200 derajat Celsius hingga keemasan dan kokoh, sekitar 18 menit atau sesuaikan dengan oven masing-masing.']::text[] WHERE id = 28;

-- Resep ID: 29 - Tenggiri kuah asam pedas
UPDATE public.recipes SET instructions = ARRAY['Cuci bersih ikan, lumuri dengan air jeruk nipis, diamkan selama 15 menit, cuci kembali sampai bersih, lalu sisihkan.', 'Rebus air dalam panci hingga mendidih.', 'Tumis bumbu sampai wangi, masukkan cabai, daun jeruk, kunyit, serai, dan jahe. Aduk-aduk sampai layu, lalu tuang tumisan bumbu ke dalam panci berisi air mendidih. Bumbui dengan garam dan gula, masukkan ikan, masak sampai mendidih kembali.', 'Masukkan belimbing wuluh dan cabai rawit utuh, masak sampai bumbu meresap. Tes rasa, sebelum diangkat masukkan irisan tomat hijau, matikan api, taburi daun bawang, lalu sajikan. (Boleh ditaburi daun kemangi bila suka)']::text[] WHERE id = 29;

-- Resep ID: 30 - Pindang Tongkol Suwir Sambal Matah
UPDATE public.recipes SET instructions = ARRAY['Suwir kasar pindang tongkol, lalu goreng dengan sedikit minyak di atas teflon sambil diaduk terus sampai agak mengering.', 'Campur bawang merah, cabai, serai, daun jeruk, garam, dan minyak kelapa, lalu remas-remas. Kemudian campur dengan ikan suwir, kucuri dengan jeruk limau, dan aduk rata.', 'Sajikan.']::text[] WHERE id = 30;

-- Resep ID: 32 - Kalio tenggiri
UPDATE public.recipes SET instructions = ARRAY['Lumuri ikan dengan air jeruk nipis, diamkan selama 15 menit, lalu cuci bersih.', 'Tumis bumbu halus, serai, daun salam, dan daun kunyit hingga bumbu matang dan harum.', 'Masukkan ikan tenggiri, aduk hingga berubah warna, lalu tambahkan santan dan wortel.', 'Masak sambil diaduk, beri gula dan garam, lalu masukkan cabai utuh.', 'Masak hingga matang, lalu sajikan.']::text[] WHERE id = 32;

-- Resep ID: 33 - Ikan Tongkol Asem Padeh Istimewa Bumbu Sederhana
UPDATE public.recipes SET instructions = ARRAY['Bersihkan ikan tongkol, buang kotoran, dan potong sesuai selera. Lumuri dengan air jeruk, diamkan selama 15-20 menit.', 'Masak air hingga mendidih, masukkan bumbu halus, serai, daun jeruk, lengkuas, dan daun kunyit. Setelah mendidih, masukkan ikan dan susun hingga semua ikan terendam dalam kuah cabe merah.', 'Masak dengan api kecil hingga air sedikit menyusut dan kuah agak mengental. Masukkan asam kandis, gula, dan garam, aduk sebentar. Uji rasa, angkat, dan siap dihidangkan.']::text[] WHERE id = 33;

-- Resep ID: 34 - Mushrooms Tuna Puff
UPDATE public.recipes SET instructions = ARRAY['Potong dadu bawang bombai, geprek dan cincang bawang putih, potong-potong jamur kancing, sisihkan.', 'Panaskan margarin, tumis bawang putih dan bawang bombai sampai harum. Masukkan tuna dan jamur kancing, tambahkan bumbu lain. Aduk sebentar, masak selama 5 menit. Koreksi rasa, angkat, sisihkan.', 'Potong puff pastry suhu ruang sesuai selera. Untuk bentuk segitiga, potong setiap lembar menjadi 4 bagian. Untuk bentuk kotak, potong menjadi 6 bagian sama besar.', 'Beri isian tuna dan potongan keju. Lipat dan rekatkan dengan menekan menggunakan ujung garpu pada semua sisi lipatan. Oles permukaannya dengan kuning telur dan taburi keju parut.', 'Panggang pada suhu 190°C selama 30 menit, atau sesuaikan dengan oven masing-masing.', 'Sajikan dengan cocolan saus sambal dan mayones.']::text[] WHERE id = 34;

-- Resep ID: 35 - Pempek tenggir
UPDATE public.recipes SET instructions = ARRAY['Blend ikan, garam, micin, bawang putih, dan setengah es batu sampai lumat.', 'Masukkan telur, setengah sagu tani, dan sisa es batu.', 'Keluarkan dari blender dan letakkan di baskom.', 'Uleni dengan sisa sagu tani dan terigu.', 'Bentuk adonan dengan memberi lubang di tengah menggunakan telunjuk.', 'Isi lubang dengan kocokan telur.', 'Rebus pempek sampai mengapung.', 'Setelah semua adonan habis, rebus kembali semua pempek selama kurang lebih 10 menit untuk memastikan telur isian matang.', 'Setelah mengapung semua, angkat dan tiriskan.', 'Pembuatan cuko:', 'Blender semua bahan all in one.', 'Tuang ke panci dan rebus sampai mendidih.', 'Matikan api, dinginkan, dan saring.', 'Cuko siap digunakan.', 'Penyajian:', 'Goreng pempek sampai kekuningan dan sajikan dengan irisan timun dan tuangi cuko.']::text[] WHERE id = 35;

-- Resep ID: 36 - Gurami Masak Saus Tiram
UPDATE public.recipes SET instructions = ARRAY['Siapkan dan timbang bahan sesuai resep.', 'Tumis bawang, cabai, daun jeruk, dan jahe hingga harum.', 'Masukkan tomat, garam, gula, saus tiram, kecap, dan sedikit air. Tunggu hingga bumbu mendidih dan matang.', 'Masukkan ikan, aduk-aduk hingga bumbu meresap.', 'Tes rasa, jika sudah pas matikan api.', 'Tata di piring saji.', 'Gurami Masak Saus Tiram siap disajikan.']::text[] WHERE id = 36;

-- Resep ID: 37 - Ikan nila kuah pindang
UPDATE public.recipes SET instructions = ARRAY['Lumuri ikan nila dengan perasan jeruk nipis dan garam. Sisihkan.', 'Haluskan kemiri dan kunyit bakar.', 'Tumis bawang merah, bawang putih, dan bumbu halus bersama daun salam serta serai.', 'Masukkan ikan nila.', 'Masukkan cabai rawit utuh, irisan cabai hijau, irisan tomat, dan beri air.', 'Masak sampai mendidih dan ikan matang. Cek rasa.', 'Ikan nila kuah pindang siap disajikan.']::text[] WHERE id = 37;

-- Resep ID: 38 - Tongkol&Jengkol Balado
UPDATE public.recipes SET instructions = ARRAY['Cuci bersih ikan, kemudian lumuri dengan air jeruk nipis dan beri sedikit garam. Diamkan sebentar.', 'Panaskan minyak goreng, masukkan jengkol. Masak hingga jengkol empuk, buang kulitnya, dan pipihkan. Sisihkan. Kemudian goreng ikan tongkol sampai matang. Angkat dan tiriskan.', 'Jika minyak terlalu kotor, ganti dengan yang baru. Masukkan bumbu halus, tambahkan garam, kemudian masak hingga bau langu cabai hilang. Tambahkan kaldu jamur. Tes rasa. Jika sudah pas, campur rata tongkol dan jengkol dengan bumbu balado. Pindahkan ke wadah dan sajikan.']::text[] WHERE id = 38;

-- Resep ID: 39 - Tongkol suwir  kemangi
UPDATE public.recipes SET instructions = ARRAY['Cuci bersih ikan tongkol, lalu goreng hingga matang. Setelah dingin, suwir-suwir dagingnya.', 'Haluskan bumbu (bawang merah, bawang putih, cabai, tomat). Tumis bumbu halus hingga harum dan airnya habis. Masukkan daun jeruk, tumis kembali.', 'Masukkan suwiran ikan tongkol ke dalam tumisan bumbu. Beri sedikit air, garam, dan kaldu. Masak hingga bumbu meresap. Masukkan kemangi, lalu sajikan.']::text[] WHERE id = 39;

-- Resep ID: 40 - Pecak Gurame
UPDATE public.recipes SET instructions = ARRAY['Bersihkan ikan lalu cuci bersih. Lumuri dengan jeruk nipis. Biarkan selama 15 menit.', 'Haluskan bumbu ikan lalu lumuri ke badan ikan hingga rata. Biarkan selama 15 menit.', 'Goreng ikan hingga kering dengan api kecil. Jangan balik sebelum benar-benar kering. Tutup penggorengan. Angkat dan tiriskan.', 'Buat bumbu pecak. Sangrai bumbu pecak hingga kering lalu tumbuk kasar.', 'Tumis bumbu pecak hingga harum. Masukkan bumbu pelengkap seperti serai, daun jeruk, dan tomat hijau. Masak hingga wangi.', 'Masukkan air, air asam, gula, dan garam. Aduk rata lalu koreksi rasa. Masak hingga air tinggal sedikit.', 'Tata di piring saji. Siram ikan gurame goreng dengan sambal pecak.', 'Sajikan.']::text[] WHERE id = 40;

-- Resep ID: 41 - Pizza Tuna Jagung
UPDATE public.recipes SET instructions = ARRAY['Hidupkan ragi dengan sedikit air hangat dan gula pasir. Biarkan hingga berbuih, tanda ragi aktif.', 'Siapkan wadah, tuang terigu, garam, minyak goreng, dan campuran ragi instan tadi sedikit demi sedikit. Uleni hingga kalis.', 'Diamkan adonan selama 30 hingga 60 menit. Tutup dengan serbet basah atau cling wrap. Biarkan hingga adonan mengembang dua kali lipat.', 'Sementara itu, tumis topping hingga harum dan sisihkan.', 'Panaskan oven. Olesi loyang dengan sedikit minyak goreng. Pipihkan adonan, tusuk-tusuk dengan garpu. Olesi adonan dengan minyak goreng tipis-tipis.', 'Kemudian tuang saus bolognese, ratakan. Taburi oregano dan keju mozarella.', 'Panggang selama sekitar 20 menit. Sajikan.']::text[] WHERE id = 41;

-- Resep ID: 42 - Mujair Oseng Cabe
UPDATE public.recipes SET instructions = ARRAY['Bersihkan ikan, kerat-kerat punggungnya, cuci bersih, lalu rendam dalam rendaman bumbu ikan selama 15 menit. Goreng ikan hingga matang.', 'Panaskan sedikit minyak, tumis semua bumbu iris hingga matang. Tambahkan sedikit air, koreksi rasa.', 'Siram ikan mujair goreng dengan bumbu tumisan. Sajikan panas.']::text[] WHERE id = 42;

-- Resep ID: 43 - Lele Goreng
UPDATE public.recipes SET instructions = ARRAY['Siangi ikan lele, bersihkan isi perutnya. Kerat-kerat bagian badan.', 'Lumuri ikan dengan bumbu halus (bawang putih, kunyit, ketumbar, garam atau bumbu marinasi ikan) dan air jeruk nipis. Diamkan selama 15 menit.', 'Goreng dalam minyak panas dan banyak hingga matang dan berwarna kuning keemasan.', 'Angkat, tiriskan, dan sajikan dengan sambal dan lalapan.']::text[] WHERE id = 43;

-- Resep ID: 44 - Pindang tongkol suwir pedas
UPDATE public.recipes SET instructions = ARRAY['Panaskan minyak, tumis bawang merah hingga harum, lalu masukkan bumbu halus, daun jeruk, serai, dan lengkuas. Tumis hingga bumbu halus matang.', 'Masukkan ikan yang sudah disuwir-suwir.', 'Aduk hingga rata, tambahkan garam, penyedap rasa, dan sedikit gula.', 'Masak hingga ikan matang dan bumbu meresap ke dalam ikan.', 'Angkat jika bumbu sudah meresap dan siap disajikan dengan nasi hangat.']::text[] WHERE id = 44;

-- Resep ID: 45 - Ikan kembung cabe ijo resep bedinde
UPDATE public.recipes SET instructions = ARRAY['Cuci bersih ikan dengan air. Keluarkan isi perutnya. Rendam dalam perasan jeruk nipis selama kurang lebih 15 menit. Bilas kembali dengan air.', 'Goreng ikan sampai matang dalam minyak panas. Angkat dan sisihkan.', 'Tumis irisan bawang putih sampai harum dengan minyak goreng. Kemudian masukkan irisan bawang merah, aduk rata.', 'Terakhir masukkan irisan cabai hijau besar dan cabai hijau keriting. Beri garam dan gula pasir. Tes rasa. Jika suka, masukkan pete di akhir agar masih terasa renyah. Siram ikan dengan perasan jeruk limau.']::text[] WHERE id = 45;

-- Resep ID: 46 - Nasi Goreng Salmon
UPDATE public.recipes SET instructions = ARRAY['Tumis sebagian bawang putih dan sedikit garam dengan 2 sendok makan minyak sayur. Masukkan salmon fillet yang sudah dipotong dadu, masak sampai matang. Sisihkan.', 'Masukkan kembali 2 sendok makan minyak sayur, lalu tumis sisa bawang putih, bawang merah, dan garam sampai wangi. Masukkan kecap manis, kemudian nasi dan lada sesuai selera. Aduk rata.', 'Setelah rasa sudah pas, masukkan ikan salmon. Tumis kembali sampai semua tercampur rata. Angkat.', 'Nasi goreng salmon siap disantap.']::text[] WHERE id = 46;

-- Resep ID: 47 - Gulai Ikan Tuna
UPDATE public.recipes SET instructions = ARRAY['Cuci ikan tuna sampai bersih. Peras jeruk lemon dan tambahkan garam. Aduk rata dan diamkan selama 30 menit hingga bau amis hilang.', 'Sambil menunggu ikan, haluskan bawang merah, bawang putih, cabai, kemiri, kunyit, dan jahe.', 'Tumis bumbu halus dengan sedikit minyak hingga harum. Masukkan serai, lengkuas, daun jeruk, dan daun salam. Tumis hingga bumbu matang dan harum, kemudian tambahkan air.', 'Setelah air mendidih, masukkan ikan tuna beserta potongan tomat dan cabai rawit merah.', 'Tunggu hingga ikan matang dan air sedikit berkurang. Tambahkan garam dan gula sesuai selera, aduk sebentar. Masukkan santan instan, aduk perlahan hingga mendidih.', 'Koreksi rasa. Masukkan kacang panjang yang sudah dipotong-potong dan daun bawang. Tutup sebentar hingga kacang panjang matang. Jika rasa sudah pas, matikan kompor dan siap disajikan.']::text[] WHERE id = 47;

-- Resep ID: 56 - Perkedel Tahu
UPDATE public.recipes SET instructions = ARRAY['Hancurkan tahu putih hingga halus menggunakan garpu.', 'Haluskan bawang merah, bawang putih, ketumbar, kencur, dan cabai rawit.', 'Campur tahu halus dengan bumbu halus, daun bawang, daun jeruk, tepung beras, dan putih telur. Tambahkan garam, gula, dan merica.', 'Ambil sedikit adonan, kepal-kepal hingga berbentuk lonjong pipih. Goreng dalam minyak panas dengan api kecil sampai matang.', 'Angkat dan tiriskan. Perkedel tahu siap disajikan.']::text[] WHERE id = 56;

-- Resep ID: 57 - Tahu aci
UPDATE public.recipes SET instructions = ARRAY['Belah tahu membentuk segitiga, lalu rendam dengan air garam. Kerok bagian dalam tahu, sisihkan tahunya. Remas-remas isian tahu, lalu sisihkan.', 'Didihkan air di panci bersama bawang putih halus.', 'Campur tepung dengan kaldu bubuk, garam, daun bawang, dan isi tahu yang sudah diremas-remas. Tuangi air panas sedikit demi sedikit sambil diaduk rata.', 'Panaskan minyak goreng yang banyak. Ambil tahu, lalu beri isian. Goreng dalam minyak panas hingga matang. Jika tidak ingin langsung digoreng, bisa direbus atau dikukus sebentar, lalu simpan di kulkas.', 'Untuk membuat stok di kulkas, tahu aci bisa direbus sebentar atau dikukus terlebih dahulu sebelum dimasukkan ke kulkas.']::text[] WHERE id = 57;

-- Resep ID: 58 - Tahu Aci Pedas Manis
UPDATE public.recipes SET instructions = ARRAY['Haluskan tahu dengan sendok atau garpu, lalu campur dengan bumbu halus (takaran 1). Masukkan kocokan telur dan tepung kanji, beri garam dan merica, aduk rata.', 'Adonan yang dihasilkan tidak terlalu padat, asalkan bisa dibulat-bulatkan.', 'Panaskan air hingga mendidih, lalu masukkan bulatan adonan. Masak sekitar 10 menit atau sampai adonan mengambang, angkat, tiriskan, dan tunggu hingga dingin.', 'Panaskan minyak goreng, lalu masukkan hasil rebusan adonan. Goreng hingga matang kecoklatan dan berkulit, angkat, tiriskan.', 'Tumis sisa bumbu halus (takaran 2) sampai harum, lalu masukkan bahan saus. Aduk rata, koreksi rasa, lalu masukkan bulatan adonan yang sudah digoreng. Masukkan daun bawang, aduk rata.', 'Sajikan.']::text[] WHERE id = 58;

-- Resep ID: 59 - Sup Baso Ayam Enoki plus Tahu
UPDATE public.recipes SET instructions = ARRAY['Siapkan bahan. Iris jamur enoki dan bawang bombai kecil-kecil. Potong tahu kotak-kotak besar.', 'Campurkan daging, jamur enoki, bawang bombai, dan seluruh bumbu bakso.', 'Aduk rata hingga mengental.', 'Panaskan air hingga mendidih, kemudian masukkan seluruh bumbu sup. Masukkan bakso daging dengan sendok satu per satu. Kemudian masukkan sayur dan tahu. Koreksi rasa jika perlu.', 'Sajikan dalam keadaan hangat bersama dengan nasi hangat.']::text[] WHERE id = 59;

-- Resep ID: 61 - Tahu kulit bumbu kecap
UPDATE public.recipes SET instructions = ARRAY['Panaskan wajan.', 'Tumis semua bumbu sampai matang.', 'Tambahkan 1 gelas air.', 'Tambahkan kecap manis.', 'Masukkan tahu kulit.', 'Tunggu sampai airnya menyusut.', 'Tes rasa.', 'Angkat dan sajikan.']::text[] WHERE id = 61;

-- Resep ID: 62 - Sundubu Jjigae (sup tahu pedas ala korea)
UPDATE public.recipes SET instructions = ARRAY['Panaskan minyak, tumis bumbu halus sampai harum atau matang. Tambahkan air, biarkan mendidih.', 'Masukkan tahu, tauge, dan kol. Bumbui dengan garam, gula, bubuk cabai, dan air jeruk nipis. Masak sampai sayuran matang, koreksi rasanya.', 'Setelah pas, masukkan telur, aduk, masak sampai telur matang. Sesaat sebelum diangkat, tambahkan irisan daun bawang dan bawang bombay.', 'Sup tahu pedas ala Korea siap disajikan.']::text[] WHERE id = 62;

-- Resep ID: 63 - Tahu Fantasy
UPDATE public.recipes SET instructions = ARRAY['Masukkan semua bahan ke wadah bersih, aduk rata. Goreng sedikit untuk tes rasa.', 'Masukkan adonan ke cetakan putu ayu atau kue talam, padatkan, kemudian kukus kurang lebih 10 menit di kukusan yang telah dipanaskan terlebih dahulu.', 'Keluarkan dari cetakan semuanya, kemudian dinginkan.', 'Panaskan minyak goreng, kemudian goreng tahu fantasy sampai kuning keemasan.', 'Angkat dan tiriskan. Goreng hingga tahu habis.', 'Tahu fantasy siap disajikan.']::text[] WHERE id = 63;

-- Resep ID: 64 - Tahu Mahkota Sosis
UPDATE public.recipes SET instructions = ARRAY['Campur semua bahan menjadi satu kecuali sosis. Tes rasa dengan menggoreng sedikit adonan.', 'Olesi loyang muffin dengan minyak goreng.', 'Masukkan adonan tahu ke dalam loyang muffin, beri irisan sosis di tengahnya.', 'Kukus sampai matang.', 'Celupkan tahu yang sudah dikukus ke dalam kocokan telur, goreng sampai kecoklatan.']::text[] WHERE id = 64;

-- Resep ID: 65 - Tahu Telur Asin
UPDATE public.recipes SET instructions = ARRAY['Potong tahu menjadi 4 bagian, sisihkan.', 'Panaskan penggorengan. Siapkan tepung bumbu, lalu balurkan tahu ke dalam tepung. Goreng tahu tanpa dibolak-balik hingga berwarna kecokelatan. Balik sekali, lalu angkat jika kedua sisi sudah matang.', 'Untuk saus: ambil bagian kuning telur asin, hancurkan, dan beri air.', 'Tumis bawang putih cincang dan irisan cabai hingga harum. Masukkan kuning telur asin, tumis hingga matang dan mengental. Matikan kompor. Masukkan tahu yang telah digoreng, lalu tata di piring.', 'Sajikan.']::text[] WHERE id = 65;

-- Resep ID: 67 - Bola-Bola Tahu Isi Sosis Keju
UPDATE public.recipes SET instructions = ARRAY['Haluskan tahu putih menggunakan garpu atau tangan.', 'Haluskan semua bahan bumbu halus.', 'Campurkan tahu yang sudah dihaluskan, bumbu halus, tepung terigu, tepung tapioka, kuning telur, dan daun bawang.', 'Ambil satu sendok adonan, pipihkan, lalu isi dengan sosis dan keju parut. Bulatkan adonan.', 'Celupkan bola-bola ke dalam putih telur, lalu lumuri dengan tepung roti atau panir.', 'Simpan di freezer selama 15 menit agar tepung roti menempel dan tidak lepas saat digoreng.', 'Goreng dalam minyak banyak dengan api sedang hingga bagian dalamnya matang sempurna.', 'Bola-bola tahu isi sosis keju siap disajikan.']::text[] WHERE id = 67;

-- Resep ID: 68 - Kare Ayam-Tahu
UPDATE public.recipes SET instructions = ARRAY['Siapkan dan timbang bahan sesuai resep.', 'Tumis semua bumbu kecuali garam dan gula sampai harum.', 'Masukkan ayam, masak hingga layu. Masukkan air, tahu, dan gula. Masak hingga ayam empuk dan bumbu meresap.', 'Masukkan garam dan santan, tunggu hingga mendidih. Tes rasa, jika sudah pas matikan api. Tata di piring saji.']::text[] WHERE id = 68;

-- Resep ID: 69 - Tahu cabe garam
UPDATE public.recipes SET instructions = ARRAY['Potong tahu menjadi kotak-kotak kecil.', 'Campurkan tahu dengan tepung tapioka dan 1 sendok makan masako, aduk hingga rata.', 'Goreng tahu hingga kecoklatan, lalu tiriskan.', 'Panaskan 1 sendok makan minyak goreng, tumis cabai iris dan bawang putih cincang hingga harum. Masukkan tahu goreng, aduk rata. Tambahkan daun bawang iris tipis, aduk sebentar, lalu angkat.']::text[] WHERE id = 69;

-- Resep ID: 70 - Tahu crispy
UPDATE public.recipes SET instructions = ARRAY['Potong tahu menjadi dadu kecil, cuci bersih, dan tiriskan.', 'Rendam tahu dengan bawang putih yang sudah dihaluskan dan beri sedikit air. Tambahkan garam sejumput, diamkan selama 15 sampai 20 menit agar bumbu meresap.', 'Dalam satu wadah, masukkan tapioka, tepung instan, dan kaldu ayam atau sapi bubuk sesuai selera. Aduk merata.', 'Panaskan minyak dalam wajan. Ambil beberapa tahu, lalu lumuri dengan adonan kering tepung campuran tadi. Goreng dengan minyak panas menggunakan api kecil. Lakukan sampai habis. Tahu crispy siap disajikan dengan taburan bubuk cabai atau bubuk perasa lainnya.']::text[] WHERE id = 70;

-- Resep ID: 71 - Tahu Gejrot Cirebon
UPDATE public.recipes SET instructions = ARRAY['Goreng tahu sebentar, lalu tiriskan.', 'Ulek cabai rawit dan cabai hijau kecil hingga agak halus, kemudian ulek kasar bawang merah dan bawang putih. Setelah itu, ulek gula merah. Bumbui dan beri sedikit air.', 'Siram kuah di atas tahu pong yang sudah dipotong menjadi 4 bagian. Sajikan.']::text[] WHERE id = 71;

-- Resep ID: 72 - Rolade Tahu Sosis
UPDATE public.recipes SET instructions = ARRAY['Hancurkan tahu dan peras dengan kain atau saringan untuk mengurangi kadar airnya.', 'Tambahkan bawang putih halus, lada putih bubuk, 1 butir telur, tepung terigu, buncis, wortel, daun bawang, garam, dan gula. Aduk rata. Tes rasa.', 'Kocok lepas 2 butir telur lalu dadar tipis-tipis. (Kira-kira bisa menjadi 3 lembar dadar)', 'Ambil selembar dadar. Taruh dan ratakan secukupnya adonan tahu di atasnya. Lipat sisi kiri dan kanannya. Letakkan satu buah sosis di atasnya, lalu gulung padatkan dan kemudian bungkus dengan daun pisang atau aluminium foil.', 'Didihkan air dalam panci pengukus. Kukus rolade tahu sosis sekitar 30 menit. Dinginkan baru kemudian dipotong-potong. Sajikan dengan sambal kecap atau saus sambal.']::text[] WHERE id = 72;

-- Resep ID: 74 - Batagor tahu
UPDATE public.recipes SET instructions = ARRAY['Hancurkan tahu hingga agak lumat.', 'Haluskan bawang putih, garam secukupnya, dan merica secukupnya dengan ulekan atau blender.', 'Campurkan bumbu halus dengan tahu, terigu, telur, dan daun bawang. Aduk hingga rata.', 'Panaskan minyak. Bentuk adonan menjadi bulat-bulat dengan sendok, lalu goreng hingga berwarna keemasan.', 'Tiriskan dan angkat.', 'Panaskan air untuk membuat sambal pecel. Tambahkan sedikit garam atau ulek cabe lagi sesuai selera.', 'Hidangkan batagor tahu dengan sambal pecel.']::text[] WHERE id = 74;

-- Resep ID: 76 - Telur crispy
UPDATE public.recipes SET instructions = ARRAY['Dadar telur tipis-tipis, lalu potong persegi panjang.', 'Campur tepung bumbu dengan maizena, lalu aduk rata.', 'Celup telur ke dalam telur kocok, lalu gulingkan ke tepung kering sambil diremas-remas pelan. Goreng dalam minyak panas hingga kuning keemasan. Angkat dan sajikan.']::text[] WHERE id = 76;

-- Resep ID: 77 - Sate Telur Gulung Crispy
UPDATE public.recipes SET instructions = ARRAY['Ambil satu potongan sosis, tusuk pada tusukan sate pelan-pelan. Pastikan sebagian ujung tusuk sate lebih pipih sehingga potongan sosis bisa masuk semua dengan sempurna. Lakukan sampai habis. Sisihkan.', 'Masukkan sisa semua bahan ke dalam wadah yang ujungnya lancip atau bercorong agar nanti mudah saat menuangkannya.', 'Kocok telur sampai rata. Pastikan adonan tidak terlalu kental dan tidak terlalu encer.', 'Tempatkan rantang di atas kompor, tuangi minyak sampai 3/4 bagian. Pastikan ketika tusuk sate dicelupkan ke dalam minyak, sosis terendam semua.', 'Panaskan minyak dengan api sedang sampai benar-benar panas. Celupkan setengah batang tusuk sate sambil tetap dipegang, diamkan sebentar sampai sosis matang.', 'Dengan posisi tusuk sate masih terendam di minyak, tuang kocokan telur secukupnya sambil diaduk-aduk dengan arah melingkar menggunakan tusuk sate. Gulung secepatnya ke pinggir rantang untuk membantu telur tergulung dengan rapi. Setelah berwarna kuning keemasan, angkat.', 'Lakukan proses menggoreng sampai selesai. Tata sate telur sosis di atas tisu makan.', 'Jika suka, potong gagang sate lebih pendek agar lebih rapi dan tidak terlalu panjang.', 'Sajikan hangat-hangat dengan saus sambal atau mayones sesuai selera.', 'Setiap kali akan menuangkan adonan telur ke minyak, sebaiknya selalu dikocok terlebih dahulu agar putih telur tidak mengendap di bawah, sehingga hasilnya lebih bersarang dan crispy.']::text[] WHERE id = 77;

-- Resep ID: 78 - Telur ceplok masak tauco
UPDATE public.recipes SET instructions = ARRAY['Tumis bawang merah dan bawang putih serta cabai hingga harum. Masukkan tomat, aduk rata. Masukkan tauco, kecap manis, kecap asin, dan gula, aduk rata.', 'Tuangi air secukupnya, tunggu hingga mendidih. Masukkan telur ceplok, masak hingga bumbu meresap. Tes rasa, jika sudah pas, angkat dan sajikan.']::text[] WHERE id = 78;

-- Resep ID: 81 - Cah Timun Telur
UPDATE public.recipes SET instructions = ARRAY['Buat telur orak-arik.', 'Tumis bawang putih dan jahe dengan sedikit minyak sampai wangi dan kecokelatan.', 'Masukkan air, biarkan mendidih, lalu masukkan timun dan telur orak-arik. Beri sisa bumbu, aduk rata. Masak sebentar saja, angkat, dan sajikan.']::text[] WHERE id = 81;

-- Resep ID: 82 - Cheese Egg Toast
UPDATE public.recipes SET instructions = ARRAY['Kocok lepas telur, garam, merica, dan bon cabe. Masukkan daun bawang, keju, tomat, sosis, dan bawang bombay. Sisihkan.', 'Panaskan pan anti lengket dengan sedikit minyak. Ambil selembar roti, celupkan ke dalam kocokan telur (jangan terlalu lama agar tidak hancur). Masak hingga kedua sisi matang. Angkat. Ulangi hingga habis.', 'Sajikan hangat dengan mayones dan sambal.']::text[] WHERE id = 82;

-- Resep ID: 83 - Makaroni Telor
UPDATE public.recipes SET instructions = ARRAY['Didihkan air lalu beri garam dan sedikit minyak. Rebus makaroni hingga empuk, tiriskan.', 'Kocok telur dengan kaldu bubuk dan merica.', 'Panaskan sedikit minyak goreng, lalu masukkan makaroni. Tumis sebentar, kemudian masukkan kocokan telur. Aduk hingga matang, matikan kompor.', 'Beri bumbu tabur dan cabe bubuk sesuai selera.', 'Sajikan hangat.']::text[] WHERE id = 83;

-- Resep ID: 85 - Pindang TELUR
UPDATE public.recipes SET instructions = ARRAY['Campur semua bahan dan bumbu dalam wadah atau wajan. Rebus hingga air habis atau tersisa sedikit dan bumbu meresap.', 'Sajikan.']::text[] WHERE id = 85;

-- Resep ID: 86 - Dadar Tahu Telur
UPDATE public.recipes SET instructions = ARRAY['Hancurkan tahu dengan garpu. Campur telur dengan semua bahan. Panaskan pan, beri secukupnya minyak, tuang adonan, goreng hingga satu sisi mulai mengeras dan kecokelatan. Balik, goreng hingga matang. Sajikan.', 'Jika tidak ada cabai merah giling, bisa diganti dengan irisan cabai merah atau rawit.']::text[] WHERE id = 86;

-- Resep ID: 87 - Telur Acak mixed sayuran
UPDATE public.recipes SET instructions = ARRAY['Tumis bawang putih dan bawang merah hingga harum.', 'Masukkan campuran sayuran beku, garam, gula, dan merica bubuk. Tambahkan sedikit air, lalu masak hingga air surut dan sayuran matang.', 'Masukkan daun bawang dan telur, lalu aduk-acak bersamaan dengan sayuran hingga telur matang seperti telur orak-arik.', 'Angkat dan sajikan.']::text[] WHERE id = 87;

-- Resep ID: 89 - Tumis Brokoli Tahu Telur Jamur
UPDATE public.recipes SET instructions = ARRAY['Potong brokoli per kuntum, cuci bersih, seduh dengan air panas, tiriskan, dan sisihkan.', 'Potong jamur sesuai selera, cuci bersih, dan sisihkan.', 'Potong tahu telur agak tebal (1 tahu menjadi 6 potong), goreng dengan minyak agak banyak hingga berkulit, lalu sisihkan.', 'Tumis bawang putih dengan sedikit minyak hingga harum, lalu masukkan jamur kuping.', 'Masukkan tahu telur, beri sedikit air, lalu tambahkan saus tiram, minyak wijen, dan kecap asin. Aduk rata.', 'Masukkan brokoli, aduk rata sebentar, lalu koreksi rasa.', 'Angkat dan hidangkan.']::text[] WHERE id = 89;

-- Resep ID: 91 - Cah Toge dan Telur Dadar
UPDATE public.recipes SET instructions = ARRAY['Dadar telur dengan sedikit garam dan lada. Iris panjang-panjang. Sisihkan.', 'Panaskan sedikit minyak, tumis bawang merah dan bawang putih serta cabai sampai harum.', 'Masukkan toge, daun bawang, dan telur. Masukkan juga bumbu-bumbu. Koreksi rasa.', 'Masak sampai toge layu agar masih renyah.']::text[] WHERE id = 91;

-- Resep ID: 92 - Telur Kukus Diet
UPDATE public.recipes SET instructions = ARRAY['Kocok telur yang sudah ditambahkan air.', 'Tambahkan irisan sosis, wortel, bawang merah, dan bawang putih.', 'Bumbui dengan garam, kaldu, dan lada.', 'Masukkan adonan telur ke dalam wadah tahan panas.', 'Kukus adonan sampai matang. Untuk lapisan atas yang halus, buka sedikit tutup kukusan. Untuk hasil yang lebih cepat matang tetapi lapisan atas berbuih, tutup rapat kukusan.', 'Sajikan dengan sambal campuran kecap, bawang merah, dan cabai hijau.']::text[] WHERE id = 92;

-- Resep ID: 93 - Semur Kecap Telur Tahu
UPDATE public.recipes SET instructions = ARRAY['Panaskan minyak, tumis bumbu halus, lengkuas, dan daun salam hingga harum dengan api kecil.', 'Beri 160 ml air, tambahkan garam, gula pasir, merica, kaldu bubuk, dan kecap manis. Aduk rata dan koreksi rasa.', 'Masukkan tahu dan telur, aduk pelan. Masak hingga air menyusut dan bumbu meresap.', 'Sajikan bersama bawang goreng.']::text[] WHERE id = 93;

-- Resep ID: 95 - Egg and Beef Casserole
UPDATE public.recipes SET instructions = ARRAY['Pecahkan telur dan pastikan telur dalam keadaan segar. Sisihkan.', 'Tumis bawang bombay hingga harum. Masukkan daging cincang. Setelah daging matang, masukkan pasta tomat. Tambahkan air. Beri garam. Tes rasa. Jika sudah pas, matikan api. Sisihkan.', 'Saus putih: di wajan berbeda, masukkan cooking cream, keju quick melt, dan parmesan. Aduk rata. Jika kurang asin, boleh tambahkan garam. Terakhir, masukkan italian herbs. Aduk rata. Tunggu hingga sedikit mengental. Matikan api. Sisihkan.', 'Ambil aluminium foil berisi telur. Beri sejumput keju parut di atasnya. Ratakan. Beri satu sendok makan tumisan daging tomat. Ratakan. Di atasnya, beri satu sendok makan saus putih. Ratakan. Lakukan hingga selesai.', 'Panaskan oven. Panggang dengan suhu 150 derajat Celsius selama 20 menit. (Sesuaikan waktu dengan oven masing-masing.)', 'Setelah matang, siap dinikmati.']::text[] WHERE id = 95;

-- Resep ID: 96 - Orek tempe basah bumbu ulek
UPDATE public.recipes SET instructions = ARRAY['Goreng tempe yang sudah dipotong-potong dalam minyak panas hingga matang, jangan sampai kering.', 'Tumis bumbu halus hingga harum dan benar-benar matang. Setelah bumbu matang, tuangi air secukupnya, lalu tambahkan kecap manis, gula, garam, dan penyedap. Tes rasanya.', 'Jika rasa sudah pas, masukkan tempe dan cabai hijau, lalu aduk hingga rata dan bumbu meresap. Angkat dan sajikan.']::text[] WHERE id = 96;

-- Resep ID: 97 - Tempe Melet
UPDATE public.recipes SET instructions = ARRAY['Potong tempe menjadi beberapa bagian, belah tengahnya jangan sampai putus. Lebih baik potong tempe agak tebal. Sisihkan.', 'Tumis bahan isi. Semua bahan diblender terlebih dahulu, lalu ditumis sampai matang. Beri sedikit garam.', 'Ambil tempe yang sudah dibelah, masukkan isian di tengah-tengah tempe.', 'Masukkan tempe ke dalam adonan tepung bumbu. Jangan terlalu encer dan jangan terlalu kental. Tambahkan daun bawang ke dalam adonan tepung. Goreng tempe hingga matang dan sajikan hangat-hangat.']::text[] WHERE id = 97;

-- Resep ID: 98 - Tempe isi Sambel
UPDATE public.recipes SET instructions = ARRAY['Ulek kasar semua bahan sambal kecuali kemangi. Tumis sebentar dengan sedikit minyak. Tambahkan kemangi, aduk rata, lalu sisihkan.', 'Potong tempe dan iris bagian tengahnya tanpa putus. Isi dengan sambal tumis tadi.', 'Siapkan tepung bumbu, beri air, dan aduk hingga menjadi adonan kental.', 'Panaskan minyak goreng. Lumuri tempe isi dengan adonan basah tepung hingga tertutup merata.', 'Goreng hingga matang.', 'Sajikan.']::text[] WHERE id = 98;

-- Resep ID: 100 - Lodeh TKL (tempe, kacang panjang, labu siam)
UPDATE public.recipes SET instructions = ARRAY['Iris tipis tempe, labu siam, dan kacang panjang.', 'Blender bumbu yang harus dihaluskan.', 'Tumis bumbu halus sampai harum, kemudian tuangkan air.', 'Masukkan labu siam dan kacang panjang.', 'Setelah air sedikit berkurang, masukkan potongan tempe.', 'Masukkan santan kara yang sudah dicampur dengan air.', 'Beri sedikit garam dan penyedap rasa.', 'Tes rasa dan tunggu sampai sedikit mendidih.', 'Lodeh TKL siap disajikan.']::text[] WHERE id = 100;

-- Resep ID: 102 - Keripik Tempe Sagu Tani
UPDATE public.recipes SET instructions = ARRAY['Siapkan wadah kering dan bersih. Buka bungkus tempe, lalu campurkan tempe dengan tepung tapioka di dalam wadah. Aduk menggunakan sendok atau centong nasi, jangan terkena air dan tangan.', 'Aduk hingga tercampur rata, lalu masukkan adonan ke dalam plastik. Padatkan dan ikat plastik tersebut. Lakukan hingga adonan habis.', 'Ikat dan gantung tempe dengan tali rafia. Tusuk-tusuk tempe dengan lidi. Gantung selama kurang lebih 24 jam.', 'Tanda tempe telah jadi adalah munculnya busa-busa putih khas tempe dan tepung tidak terlihat lagi.', 'Iris tempe tipis-tipis, lalu masukkan ke dalam celupan air yang sudah dicampur bawang putih dan garam. Celupkan dengan cepat, kemudian goreng hingga matang. Angkat dan tiriskan.', 'Simpan keripik tempe sagu tani dalam wadah kedap udara. Siap disantap kapan saja.']::text[] WHERE id = 102;

-- Resep ID: 103 - Orek tempe tahu
UPDATE public.recipes SET instructions = ARRAY['Goreng tahu dan tempe hingga matang, lalu sisihkan.', 'Tumis bumbu halus hingga matang, masukkan tempe dan tahu yang sudah digoreng. Tambahkan kecap manis, aduk rata. Beri air, gula, dan garam. Aduk-aduk hingga bumbu meresap. Sajikan.']::text[] WHERE id = 103;

-- Resep ID: 104 - Perkedel Tempe
UPDATE public.recipes SET instructions = ARRAY['Kukus tempe selama 20-25 menit.', 'Haluskan tempe selagi masih panas.', 'Goreng bawang putih dan bawang merah, lalu haluskan.', 'Campurkan semua bahan, lalu aduk rata.', 'Bentuk adonan sesuai selera.', 'Goreng dalam minyak yang sudah panas hingga matang. Jangan dibalik sebelum kering agar tidak hancur. Balik sekali saja agar perkedel tempe kering dan tidak berminyak. Angkat dan tiriskan.', 'Sajikan.']::text[] WHERE id = 104;

-- Resep ID: 105 - Bakso Tempe
UPDATE public.recipes SET instructions = ARRAY['Kukus tempe yang sudah dipotong dadu sampai layu.', 'Masukkan tempe, telur, bawang putih, merica bubuk, dan garam ke dalam food processor. (Bisa menggunakan blender atau diuleg.)', 'Haluskan sampai menjadi adonan.', 'Campurkan dengan tepung terigu dan tapioka.', 'Uleni sampai tercampur dan bisa dibentuk.', 'Didihkan air. Matikan api setelah mendidih. Olesi tangan dengan minyak, lalu bentuk bakso. Masukkan ke dalam air panas. Lakukan sampai selesai.', 'Setelah semua bakso dibentuk, nyalakan api dan masak bakso tempe sampai matang.', 'Bakso siap dibumbui dan dibakar. Bisa menggunakan kuah kaldu, bumbu kacang, atau kecap.']::text[] WHERE id = 105;

-- Resep ID: 106 - Tumis Tempe Kemangi
UPDATE public.recipes SET instructions = ARRAY['Potong-potong tempe, lalu rendam sebentar dalam bahan rendaman. Goreng hingga kecoklatan, angkat, dan sisihkan.', 'Haluskan semua bahan (ulek kasar saja). Tumis dengan sedikit minyak hingga harum dan cabai matang.', 'Masukkan tempe, aduk sebentar. Tambahkan kemangi dan garam, aduk rata. Koreksi rasa, angkat, dan sajikan.']::text[] WHERE id = 106;

-- Resep ID: 107 - Tempe Goreng Telur
UPDATE public.recipes SET instructions = ARRAY['Kukus tempe, kemudian potong memanjang seperti stik.', 'Kocok telur, terigu, dan bumbu-bumbu. Biarkan tetap ada gumpalan kecil.', 'Masukkan tempe ke dalam telur, kemudian goreng dengan api sedang hingga kuning keemasan.', 'Angkat dan tiriskan.', 'Sajikan hangat dengan saus sambal.']::text[] WHERE id = 107;

-- Resep ID: 109 - Tempe Jontor
UPDATE public.recipes SET instructions = ARRAY['Potong tempe dan lubangi bagian tengahnya.', 'Uleg bawang merah, bawang putih, kencur, gula, dan garam.', 'Buat adonan tepung cair, masukkan merica bubuk, penyedap, dan irisan daun bawang.', 'Masukkan bumbu uleg ke dalam tempe yang sudah dilubangi.', 'Masukkan tempe ke dalam tepung cair, kemudian goreng ketika minyak panas dengan api kecil.']::text[] WHERE id = 109;

-- Resep ID: 111 - Tempe Kemul
UPDATE public.recipes SET instructions = ARRAY['Campur tepung mendoan dengan kunyit dan daun kucai. Aduk rata.', 'Celup tempe ke dalam adonan, lalu goreng dalam minyak panas hingga matang.', 'Sajikan tempe kemul.']::text[] WHERE id = 111;

-- Resep ID: 112 - Tahu Tempe Bacem
UPDATE public.recipes SET instructions = ARRAY['Potong tempe dan tahu sesuai selera.', 'Dalam wajan, masukkan bumbu halus, daun salam, dan lengkuas.', 'Masukkan tempe dan tahu, beri garam dan air hingga tempe dan tahu terendam. Masukkan gula merah yang sudah disisir, masak hingga mendidih.', 'Setelah mendidih, masukkan kecap manis. Sesekali balik tempe dan tahu. Masak sampai air habis dan bumbu meresap.', 'Setelah bumbu meresap, matikan api. Goreng sebentar tahu dan tempe sebelum disajikan.']::text[] WHERE id = 112;

-- Resep ID: 113 - Sate Tempe
UPDATE public.recipes SET instructions = ARRAY['Potong tempe dadu, goreng sampai kecoklatan, tiriskan.', 'Haluskan bumbu kecuali maizena dan kecap. Rebus di wajan dengan menambahkan 100 ml air atau secukupnya. Jika suka cair, air bisa ditambahkan jadi 1 gelas. Aduk rata.', 'Setelah mendidih, tambahkan kecap dan maizena yang telah dicairkan. Aduk rata. Tes rasa. Jika sudah pas, langsung bisa digunakan untuk olesan.', 'Tusuk tempe, bisa selang seling dengan potongan mentimun, tomat, cabai, dan bawang bombay atau bawang merah. Oles dengan bumbu bakar atau celupkan tusukan tempe pada bumbu bakar.', 'Panggang di atas bara sampai matang.', 'Siap dihidangkan dengan taburan cabai dan irisan bawang merah.', 'Kucuri dengan kecap manis.', 'Sebelum dibakar di atas bara, panggang sate yang siap bakar di oven listrik memakai api atas suhu 200 derajat Celcius terlebih dulu selama 15 menit supaya bumbu meresap, baru dibakar di atas bara.']::text[] WHERE id = 113;

-- Resep ID: 114 - Tempe Kering Teri Medan
UPDATE public.recipes SET instructions = ARRAY['Potong tempe kecil memanjang, lalu goreng sampai kering.', 'Cuci teri medan hingga bersih agar tidak terlalu asin, lalu jemur sampai kering. Goreng teri medan sampai matang dan kering.', 'Tumis bumbu yang sudah dihaluskan dengan minyak agak banyak. Tambahkan daun jeruk, gula merah, gula pasir, dan garam. Aduk rata, masak hingga matang dan bumbu mendidih serta agak kental. Matikan api, lalu masukkan tempe dan teri medan yang sudah digoreng. Aduk hingga tercampur rata. Angkat dan sajikan.']::text[] WHERE id = 114;

-- Resep ID: 116 - Sempol udang
UPDATE public.recipes SET instructions = ARRAY['Blender udang, bawang putih, dan telur hingga halus, lalu tuang ke dalam wadah. Masukkan tepung-tepungan dan bumbu lainnya, aduk hingga rata.', 'Didihkan air di wajan. Bentuk sempolan di tusukan sate, lalu rebus dalam air mendidih hingga matang. Angkat dan tiriskan.', 'Panaskan minyak yang banyak di wajan. Ambil sempolan, celupkan ke dalam bahan pencelup, lalu goreng dalam minyak panas hingga matang. Angkat dan sajikan dengan saus sambal.']::text[] WHERE id = 116;

-- Resep ID: 117 - Udang Bakar
UPDATE public.recipes SET instructions = ARRAY['Belah punggung udang, bersihkan tali hitamnya, lalu cuci bersih.', 'Kucuri udang dengan perasan air jeruk nipis, aduk rata. Diamkan selama 10 menit, lalu cuci bersih.', 'Beri 1 sendok teh garam, remas-remas, dan diamkan selama 15 menit. Tiriskan jika mengeluarkan air.', 'Lumuri udang dengan tepung tapioka tipis-tipis. Goreng sebentar dalam minyak panas hanya sampai berubah warna. Angkat dan tiriskan.', 'Haluskan bawang merah dan bawang putih. Tumis di atas wajan sampai matang dan harum. Tambahkan kecap, saus sambal, garam, lada, dan kaldu bubuk. Aduk rata dengan api kecil. Koreksi rasa, matikan api, dan sisihkan.', 'Lumuri udang dengan bumbu tumisan hingga rata. Tusuk udang dengan lidi atau tusukan sate. Diamkan minimal 15 menit.', 'Bakar udang di atas bara api atau teflon hingga matang. Sajikan.']::text[] WHERE id = 117;

-- Resep ID: 118 - Udang Asam Pedas
UPDATE public.recipes SET instructions = ARRAY['Kupas udang, sisakan ekor, dan belah punggungnya. Bersihkan dengan jeruk nipis dan garam. Bilas bersih dan tiriskan.', 'Panaskan minyak, tumis bumbu halus sampai harum dan matang. Masukkan udang, aduk-aduk sampai berubah warna.', 'Masukkan air, cabai iris, tomat, dan belimbing sayur. Bumbui.', 'Setelah udang matang dan kuah mengental, masukkan asam jawa. Aduk sebentar dan siap disajikan.']::text[] WHERE id = 118;

-- Resep ID: 119 - Dimsum siomay udang ayam
UPDATE public.recipes SET instructions = ARRAY['Campur semua bahan dan bumbu menjadi satu, kecuali wortel yang diparut halus.', 'Aduk rata. Jika terlalu kering, tambahkan air sedikit.', 'Ambil kulit pangsit. Basahi sekelilingnya menggunakan air dengan jari agar kulit pangsit elastis ketika dibentuk.', 'Letakkan satu sendok adonan di tengah, lalu bentuk seperti di atas. Tambahkan parutan wortel di atasnya.', 'Kukus selama 20 hingga 30 menit. Beri jarak karena siomay akan mengembang.', 'Siomay siap dihidangkan. Bisa juga disimpan di kulkas dan dihangatkan sewaktu-waktu.']::text[] WHERE id = 119;

-- Resep ID: 120 - Siomay Ayam Udang
UPDATE public.recipes SET instructions = ARRAY['Kupas labu siam, lalu kukus hingga empuk. Angkat, biarkan dingin, lalu parut. Letakkan dalam saringan, diamkan hingga air tidak menetes. Panaskan dandang, jangan masukkan saringan dandang, untuk tempat siomay.', 'Dalam food processor, masukkan ayam, udang, dan es batu. Giling hingga halus. Tambahkan labu siam, daun bawang, bawang putih, dan bumbu. Giling hingga rata.', 'Masukkan telur, giling lagi hingga tercampur rata.', 'Pindahkan ke wadah. Masukkan tepung terigu dan tepung tapioka secara bertahap sambil diaduk hingga rata. Tes rasa.', 'Adonan akhir sangat kental, tidak jatuh saat diangkat dengan spatula. Siap diisikan ke tahu, pare, dan kol.', 'Alasi saringan dandang dengan daun pisang (bila tidak ada, oles dengan minyak goreng agar tidak lengket). Masukkan siomay. Bila akan pakai cetakan, oles cetakan dengan minyak goreng agar tidak lengket. Kukus dalam dandang yang telah dipanaskan dengan api sedang selama sekitar 20 menit.', 'Siapkan piring, beri siomay, siram dengan bumbu kacang, saus sambal, kecap manis, dan sambal. Siap disajikan.']::text[] WHERE id = 120;

-- Resep ID: 122 - Sambal Goreng Udang Lokio
UPDATE public.recipes SET instructions = ARRAY['Panaskan minyak dalam wajan, tumis bawang merah, tomat, dan bumbu tumbuk hingga harum.', 'Masukkan udang, masak hingga berubah warna. Tambahkan lokio, masak hingga layu.', 'Tambahkan garam dan gula pasir, aduk rata. Lakukan tes rasa.']::text[] WHERE id = 122;

-- Resep ID: 123 - Peyek udang
UPDATE public.recipes SET instructions = ARRAY['Aduk bahan halus dengan semua bahan lain kecuali udang. Buat adonan agak encer agar hasilnya tipis dan garing.', 'Panaskan minyak dengan api kecil.', 'Setelah minyak benar-benar panas, ambil adonan dengan sendok sayur, lalu letakkan udang di atasnya.', 'Masukkan adonan ke dalam minyak panas. Goreng hingga garing.']::text[] WHERE id = 123;

-- Resep ID: 124 - Sambel goreng udang pete
UPDATE public.recipes SET instructions = ARRAY['Rebus cabai, bawang merah, dan bawang putih, kecuali tomat.', 'Setelah udang dicuci bersih, goreng udang setengah matang saja.', 'Blender semua bahan rebusan kecuali tomat.', 'Tumis cabai yang sudah diblender hingga harum. Iris tomat, masukkan ke dalam tumisan cabai.', 'Masukkan terasi matang sambil dibejek hingga hancur. Setelah itu, masukkan pete.', 'Tes rasa.', 'Terakhir, campurkan udang. Aduk sambal goreng.', 'Sambal goreng udang pete siap dinikmati.']::text[] WHERE id = 124;

-- Resep ID: 127 - Soto Udang Medan
UPDATE public.recipes SET instructions = ARRAY['Buat kaldu udang dengan merebus kepala dan kulit udang yang sudah dicuci bersih bersama jahe geprek, daun bawang, dan bawang putih hingga air menyusut. Saring dan sisihkan.', 'Tumis bumbu halus hingga harum dan matang, kemudian masukkan daun salam, daun jeruk, dan serai.', 'Masukkan air, aduk, lalu masukkan kaldu udang. Tambahkan santan sambil terus diaduk agar santan tidak pecah.', 'Masukkan udang, bumbui, dan tambahkan air jeruk nipis. Aduk rata dan koreksi rasa.', 'Tata kol dan tauge di mangkuk, lalu siram dengan soto udang. Sajikan.']::text[] WHERE id = 127;

-- Resep ID: 129 - Chesse spaghetti aglio olio with prawn
UPDATE public.recipes SET instructions = ARRAY['Buang kepala dan kulit udang, kerat bagian punggung untuk membersihkan kotoran. Cuci di air mengalir, tambahkan sedikit perasan jeruk nipis, marinasi dengan garam dan merica. Diamkan sejenak sambil menunggu rebus spaghetti hingga matang. Jangan lupa tambahkan sedikit minyak agar tidak lengket.', 'Cincang halus bawang putih. Masukkan butter ke dalam wajan atau teflon, lalu tumis bawang putih hingga harum. Masukkan udang, masak hingga berubah warna.', 'Setelah udang berubah warna, masukkan spaghetti. Beri sedikit air, tambahkan bumbu keju tabur, Italian herbs, garam, gula pasir, kaldu bubuk, dan merica. Jangan lupa test rasa. Bila dirasa cukup, matikan api dan pindahkan ke piring saji.', 'Beri taburan cincang parsley.', 'Chesse spaghetti aglio olio with prawn siap disajikan.']::text[] WHERE id = 129;

-- Resep ID: 130 - Udang kecap pedas
UPDATE public.recipes SET instructions = ARRAY['Tumis irisan bawang merah, bawang putih, daun salam, lengkuas, dan jahe hingga harum. Masukkan udang. Tumis hingga udang berubah warna.', 'Masukkan irisan cabai besar dan kecil. Tambahkan saus tiram, kecap manis, garam, dan gula. Tumis lagi hingga rata dan bumbu meresap. Koreksi rasa.', 'Terakhir, masukkan irisan daun bawang, aduk rata. Angkat dan sajikan.']::text[] WHERE id = 130;

-- Resep ID: 131 - Udang Goreng Mentega
UPDATE public.recipes SET instructions = ARRAY['Cuci dan kupas udang, buang kepalanya, lalu belah tengah badannya. Tetesi dengan perasan jeruk nipis dan diamkan selama 15 menit.', 'Goreng udang dengan minyak panas hingga berubah warna dan merekah, lalu tiriskan.', 'Panaskan mentega atau margarin. Tumis bawang putih dan bawang bombay hingga harum. Masukkan udang. Tambahkan kecap inggris dan kecap manis. Aduk rata. Koreksi rasa, bila perlu tambahkan penyedap. Aduk rata lagi sebentar.', 'Sajikan.']::text[] WHERE id = 131;

-- Resep ID: 132 - Udang saus Padang Extra Pedas😬
UPDATE public.recipes SET instructions = ARRAY['Tumis bumbu yang dihaluskan, daun salam, daun jeruk, dan jahe hingga harum.', 'Lalu masukkan air secukupnya hingga mendidih.', 'Kemudian masukkan udang dan semua bahan.', 'Koreksi rasa. Sajikan.']::text[] WHERE id = 132;

-- Resep ID: 139 - Nasi Kebuli
UPDATE public.recipes SET instructions = ARRAY['Rebus daging dengan air secukupnya sampai setengah matang. Angkat dan sisihkan.', 'Panaskan minyak, tumis bumbu halus sampai harum. Tambahkan bumbu rempah halus, tumis kembali sampai matang.', 'Tambahkan air, biarkan mendidih, lalu masukkan daging. Masak sampai matang. Matikan api.', 'Cuci beras dan masukkan ke rice cooker. Tuang air rebusan daging beserta dagingnya, aduk rata. Total cairan 350 ml, sesuaikan dengan jenis beras masing-masing. Masak sampai matang.', 'Sajikan dengan pelengkap.']::text[] WHERE id = 139;

-- Resep ID: 140 - Sate Kambing
UPDATE public.recipes SET instructions = ARRAY['Potong dadu kecil daging kambing, lalu lumuri dengan 1 sendok teh nanas parut. Diamkan selama 20 menit.', 'Haluskan bumbu, lalu siram ke dalam daging. Campur hingga rata dan diamkan selama 20-30 menit agar bumbu meresap. Ambil tusuk sate, lalu tusukkan 4-5 potong daging.', 'Panggang atau bakar daging hingga matang.', 'Angkat sate dan hidangkan dengan sambal kecap.', 'Sambal kecap: Aduk semua bahan menjadi satu, lalu hidangkan.']::text[] WHERE id = 140;

-- Resep ID: 145 - Sate Kambing Tanpa Tusuk
UPDATE public.recipes SET instructions = ARRAY['Jika ingin lebih empuk, bisa ditambahkan nanas parut dan diamkan selama 10-15 menit. Jangan mencuci daging agar tidak amis.', 'Iris daging melawan serat. Beri bumbu marinasi, aduk rata, lalu simpan di kulkas selama 30 menit.', 'Keluarkan daging, lalu bakar. Sebaiknya menggunakan arang untuk hasil yang lebih enak.', 'Goreng bawang merah, bawang putih, dan cabai sebentar, lalu haluskan. Tumis dengan 1-2 sendok makan minyak. Masukkan daging, aduk rata. Tambahkan air agak banyak, gula, garam, dan kecap. Boleh tambahkan penyedap. Kecilkan api, ungkep hingga bumbu meresap.']::text[] WHERE id = 145;

-- Resep ID: 146 - Tongseng Kambing
UPDATE public.recipes SET instructions = ARRAY['Tumis bumbu halus bersama jahe, lengkuas, serai, dan daun-daunan hingga harum.', 'Masukkan daging kambing yang sudah dicuci bersih dan dipotong-potong sesuai selera. Aduk bersama bumbu, masak sebentar.', 'Tuangkan air lalu aduk rata. Masak sampai daging empuk.', 'Setelah hampir matang, masukkan kol, tomat, dan cabai rawit. Bumbui dan tes rasa. Masak lagi sampai daging empuk.', 'Jika air berkurang banyak, boleh tambah lagi lalu masak dan tes rasa sampai rasa dan kematangan daging sesuai.', 'Campur semua bahan acar lalu aduk rata. Cabai rawit hijau biarkan utuh saja. Lebih enak didiamkan dulu supaya meresap.', 'Sajikan tongseng dengan acarnya.']::text[] WHERE id = 146;

-- Resep ID: 148 - Tongseng Kambing
UPDATE public.recipes SET instructions = ARRAY['Rebus terlebih dahulu daging kambing hingga empuk. Jika ingin mengurangi bau kambing, rendam daging dengan air nanas terlebih dahulu.', 'Tumis bumbu halus beserta bumbu geprek hingga harum.', 'Tambahkan air, lalu masukkan daging kambing, garam, gula, lada, dan kecap. Tes rasa.', 'Terakhir, masukkan bumbu iris dan biarkan layu. Tongseng kambing siap disantap.']::text[] WHERE id = 148;

-- Resep ID: 149 - Nasi Briyani S
UPDATE public.recipes SET instructions = ARRAY['Siapkan semua bahan-bahan.', 'Masak air sekitar 2 liter hingga mendidih. Masukkan irisan daging, jahe yang sudah digeprek, dan sejumput garam. Rebus dengan api kecil hingga daging empuk. Jaga air rebusan jangan sampai habis. Jika air habis dan daging belum empuk, tambahkan air lagi. Pastikan setelah daging empuk, air rebusan tersisa sekitar 1 liter. Koreksi rasa garam.', 'Ulek semua bumbu yang dihaluskan hingga lembut. Sisihkan.', 'Di wajan terpisah, panaskan 3-4 sendok makan minyak samin. Tumis bawang bombay dan bawang putih geprek hingga harum.', 'Masukkan bumbu yang sudah dihaluskan, tumis hingga harum. Masukkan semua bumbu cemplung, aduk rata. Matikan api.', 'Masukkan bumbu tumisan ke dalam rebusan daging. Aduk rata. Masak dengan api kecil selama kurang lebih 1 jam agar bumbu meresap. Jika air menyusut kurang dari 1 liter, tambahkan air lagi. Jika daging sudah meresap bumbu, matikan api.', 'Saring rebusan daging dengan saringan besar. Ambil daging dan sisihkan. Buang residu bumbu. Gunakan kaldu untuk memasak beras.', 'Tuang 3 gelas (sekitar 750 ml) air kaldu ke dalam panci. Rebus hingga mendidih. Jika kurang asin, tambahkan sedikit garam. Masukkan beras.', 'Pastikan posisi beras 1 ruas jari lebih rendah dari air. Jika air kurang, tambahkan air panas atau kaldu. Jika terlalu banyak, kurangi. Tutup panci. Masak dengan api kecil hingga air asat, lalu buka tutup panci.', 'Tutup kembali panci rapat-rapat dengan aluminium foil, pastikan tidak ada lubang. Timpa dengan tutup panci. Masak dengan api kecil.', 'Jika tutup panci mulai berasap, nasi hampir matang. Buka aluminium foil sebentar, ambil satu centong nasi dari tengah atas. Masukkan kismis dan sejumput saffron ke dalam lubang tersebut.', 'Tutup lubang dengan nasi yang diambil tadi. Ratakan.', 'Tutup kembali dengan aluminium foil rapat. Timpa dengan tutup panci. Masak hingga nasi matang dan pulen. Buka, nasi di tengah akan berwarna merah. Aduk bagian tengah atas saja dengan sendok. Tutup kembali agar tetap hangat. Nasi siap disajikan.', 'Tempatkan nasi yang sudah matang di nampan besar.', 'Pisahkan nasi yang berwarna kuning kemerahan karena saffron ke piring. Sisihkan juga kismis.', 'Letakkan semua daging di tengah nampan. Taburi nasi kuning kemerahan di sekeliling daging hingga habis. Lakukan hal yang sama dengan kismis.', 'Taburi dengan irisan daun parsley dan kacang mede atau kacang Arab jika ada. Sajikan dengan acar.', 'Cara membuat acar: potong dadu wortel, timun, dan bawang merah. Iris kecil cabai. Campur dengan sejumput gula halus, sedikit garam, dan 1 sendok makan perasan lemon. Aduk rata.', 'Jika menggunakan daging ayam, belah ayam menjadi dua. Sebelum disajikan, panggang ayam terlebih dahulu. Lumuri ayam dengan saus tomat yang terbuat dari 2 sendok makan pasta tomat, 3 siung bawang putih parut, 1 sendok makan air perasan lemon, dan 2 sendok makan minyak zaitun. Aduk rata. Tambahkan bubuk cabai jika suka pedas.', 'Balurkan saus ke permukaan ayam hingga rata. Panggang hingga merah kecokelatan.', 'Nasi Briyani juga bisa dimasak dengan rice cooker. Caranya sama seperti memasak nasi biasa, tetapi gunakan air kaldu rebusan daging. Rendam beras selama 30 menit sebelum dimasak agar lebih pulen.', 'Untuk mempercepat memasak daging, gunakan panci presto. Setelah bumbu ditumis, campurkan daging dan bumbu, lalu masak dengan panci presto selama 20-25 menit dengan api kecil. Untuk daging ayam, cukup 15 menit.', 'Nasi Briyani bisa menggunakan beras lokal. Cara memasaknya sama, rendam beras terlebih dahulu agar cepat matang dan pulen.']::text[] WHERE id = 149;

-- Resep ID: 150 - Tahu Buncis Kuah Santan
UPDATE public.recipes SET instructions = ARRAY['Goreng tahu pong sampai kering, angkat, tiriskan, dan sisihkan.', 'Didihkan air dalam panci. Sambil menunggu air mendidih, tumis bumbu yang dihaluskan sampai harum. Masukkan batang serai, lengkuas, dan daun jeruk. Tumis sampai matang, lalu beri sedikit air dan aduk rata. Kemudian masukkan ke dalam air yang mendidih dan aduk rata kembali.', 'Masukkan santan, garam, gula, merica bubuk, dan kaldu bubuk sapi. Aduk rata. Lalu masukkan irisan buncis, tahu goreng, dan cabai rawit. Aduk rata kembali dan masak sebentar. Tes rasa. Angkat dan siap disajikan sebagai teman makan nasi dengan taburan bawang goreng.']::text[] WHERE id = 150;

-- Resep ID: 151 - Kambing Kecap
UPDATE public.recipes SET instructions = ARRAY['Tumis bawang putih, bawang merah, jahe, dan cabai rawit sampai harum dan layu.', 'Masukkan daging kambing, aduk sampai berubah warna.', 'Tambahkan kecap manis, kecap asin, garam, gula, dan air secukupnya.', 'Ungkep sampai daging empuk. Cicipi.', 'Sajikan dengan ditaburi bawang goreng.']::text[] WHERE id = 151;

-- Resep ID: 152 - Nasi Goreng Kambing
UPDATE public.recipes SET instructions = ARRAY['Panaskan minyak, tumis bumbu halus dan kayu manis hingga harum dan bumbu matang.', 'Masukkan daging kambing, garam, dan lada, aduk rata.', 'Masukkan nasi, kecap, dan lada halus, aduk hingga rata dengan api besar.', 'Sajikan nasi goreng kambing dengan taburan bawang merah goreng yang banyak dan pelengkap.']::text[] WHERE id = 152;

-- Resep ID: 154 - Gulai kambing
UPDATE public.recipes SET instructions = ARRAY['Rebus daging, tulang, dan jeroan hingga empuk, lalu angkat dan sisihkan.', 'Tumis bumbu halus hingga harum, masukkan bumbu rempah lainnya, tumis hingga bumbu benar-benar matang.', 'Didihkan santan di panci, masukkan bumbu tumis, aduk terus agar santan tidak pecah. Beri gula, garam, dan kaldu bubuk. Masukkan daging, tulang, dan jeroan kambing. Masak hingga bumbu meresap dan kuah sedikit mengental. Angkat dan sajikan.']::text[] WHERE id = 154;

-- Resep ID: 155 - Machboos al Laham (nasi kebuli kambing khas Kuwait)
UPDATE public.recipes SET instructions = ARRAY['Cuci bersih beras, lalu rendam dengan air sampai menutupi permukaan. Sisihkan. Gunakan beras long grain atau beras biasa jika tidak ada.', 'Tumis daging dengan minyak samin dan semua bumbu utama. Tutup dan diamkan dengan api sedang selama 30 menit.', 'Tambahkan 800 ml air ke dalam tumisan daging. Diamkan selama 45 menit atau sampai daging empuk.', 'Buang air rendaman beras, lalu tuang beras ke dalam rebusan daging. Aduk dan diamkan selama 10 menit sampai beras setengah matang.', 'Di penggorengan lain, tumis bawang merah iris dan kismis dengan sedikit minyak sampai keemasan dan layu. Angkat.', 'Pindahkan nasi ke dalam rice cooker, tambahkan tumisan bawang merah dan kismis, aduk rata. Masak nasi di rice cooker seperti biasa sampai matang. Setelah matang, diamkan 20 menit dengan tombol warm.', 'Sajikan di piring saji.']::text[] WHERE id = 155;

-- Resep ID: 158 - Lapis daging sapi
UPDATE public.recipes SET instructions = ARRAY['Tumis bumbu halus hingga wangi. Masukkan daun salam, serai, daun jeruk, cengkih, dan kayu manis. Aduk rata. Masukkan daging, aduk hingga berubah warna.', 'Setelah daging berubah warna, bumbui dengan garam, gula merah, air asam, dan kecap manis. Aduk rata. Tuangi air, masak hingga daging empuk dan bumbu meresap. Angkat dan sajikan.']::text[] WHERE id = 158;

-- Resep ID: 161 - Japchae with beef korean noodle 🍝 (pr_asianfood)
UPDATE public.recipes SET instructions = ARRAY['Marinasi daging sapi dengan 2 siung bawang putih halus, secuil jahe, gula, garam, merica, dan kecap asin. Campur dalam 1 wadah soun, minyak wijen, kecap asin, kecap manis, kaldu bubuk, dan gula, aduk rata.', 'Panaskan minyak goreng, tumis bawang putih dan bawang bombay hingga harum. Masukkan wortel, paprika, dan jamur, tumis hingga layu. Masukkan daging sapi, aduk terus hingga berubah warna.', 'Masukkan soun, aduk rata hingga semua bumbu menyatu. Terakhir, masukkan daun bawang, aduk sebentar. Angkat dan sajikan dengan taburan wijen.']::text[] WHERE id = 161;

-- Resep ID: 162 - Sup daging sapi simple tapi enak, cocok buat pemula
UPDATE public.recipes SET instructions = ARRAY['Cuci bersih daging, beri garam, remas-remas, lalu cuci kembali dan tiriskan.', 'Siapkan air di panci, panaskan sampai mendidih, lalu masukkan daging dan 2 siung bawang putih geprek.', 'Rebus sekitar 5 menit, buang airnya, lalu masukkan 750 ml air matang.', 'Selagi menunggu daging empuk, siapkan bahan lain.', 'Kupas wortel dan kentang, potong buncis. Rendam kentang dalam air agar tidak hitam.', 'Potong daun bawang, ikat seledri, sisihkan.', 'Setelah direbus sekitar 30 menit, masukkan bawang putih, kentang, dan wortel, lalu diamkan selama 10 menit. Kemudian masukkan bawang merah goreng, daun bawang, dan seledri.', 'Biarkan selama 5 menit, lalu masukkan tomat, buncis, dan bumbu-bumbu.', 'Diamkan sekitar 5 menit dengan api kecil.', 'Cicipi rasa, jika sudah pas, sajikan di mangkuk dengan perasan jeruk limo. Bisa juga ditaburi bawang merah goreng di atasnya.']::text[] WHERE id = 162;

-- Resep ID: 163 - Serundeng Daging Sapi
UPDATE public.recipes SET instructions = ARRAY['Presto daging dengan air secukupnya yang sudah diberi sedikit garam selama 1 menit. Tiriskan.', 'Tumis bumbu halus dan rempah sampai wangi.', 'Masukkan daging yang sudah dipresto dengan sedikit air kaldunya, asam, gula, garam, dan kaldu bubuk. Aduk rata.', 'Masukkan kelapa parut.', 'Gunakan api kecil saat memasak. Terus keruk dasar wajan sambil diaduk karena mudah gosong. Tambahkan sedikit minyak jika dirasa masih basah. Setelah kelapa dan daging agak kering, akan mudah diaduk.', 'Koreksi rasanya. Masak sampai kelapa dan daging kering kuning kecoklatan. Butuh waktu lama sekitar sejam lebih. Matikan api. Angkat dan sajikan.']::text[] WHERE id = 163;

-- Resep ID: 164 - Bakso sapi kenyal
UPDATE public.recipes SET instructions = ARRAY['Masukkan daging, bawang putih, es batu, dan minyak sayur ke dalam blender atau food chopper. Blender hingga daging halus dan semua tercampur rata.', 'Masukkan semua bahan bumbu, blender lagi hingga rata dan halus.', 'Setelah selesai diblender, bentuk dan bulatkan adonan bakso dengan sendok. Rebus bakso hingga mengapung, tanda bakso sudah matang. Angkat dan siap diolah.']::text[] WHERE id = 164;

-- Resep ID: 165 - Tofu & Beef Bowl - Gyudon Super Healthy
UPDATE public.recipes SET instructions = ARRAY['Masukkan irisan bawang bombai ke dalam wajan datar, nyalakan api, dan tumis sekitar 3 menit.', 'Masukkan daging di tengah wajan datar.', 'Masukkan tahu di pinggir wajan datar. Kemudian masukkan seluruh bumbu masak ke tengah daging.', 'Tutup wajan datar dan panaskan dengan api sedang selama 5 menit.', 'Buka wajan datar, aduk daging hingga merata, sambil terus memanaskan dengan api kecil hingga sedang selama 5 menit. Angkat dan sajikan.']::text[] WHERE id = 165;

-- Resep ID: 167 - Nasi Kebuli Daging Sapi
UPDATE public.recipes SET instructions = ARRAY['Siapkan bahan, rebus daging lalu potong-potong. Cuci beras, lalu sisihkan tanpa air.', 'Tumis bumbu halus dengan minyak dan margarin sampai harum. Masukkan ketumbar, bumbu kari instan, garam, dan bumbu rempah lainnya.', 'Masukkan air, aduk rata. Masukkan daging lalu masak sampai daging empuk. Setelah matang, matikan kompor.', 'Tuang rebusan ke dalam panci magicom, aduk rata. Masak di magicom sambil sesekali diaduk. Setelah matang, aduk lagi lalu biarkan selama 30 menit supaya nasi tanak.', 'Sajikan bersama pelengkapnya.']::text[] WHERE id = 167;

-- Resep ID: 168 - Bulgogi (Semur Daging Sapi ala Korea)
UPDATE public.recipes SET instructions = ARRAY['Siapkan wadah bertutup, campur semua bahan marinasi (kecuali wijen dan daun bawang), aduk rata. Masukkan daging sapi lalu aduk rata kembali.', 'Tutup wadah atau bungkus dengan plastik wrap. Rendam atau marinasi minimal 2 jam. Untuk hasil terbaik, rendam semalaman.', 'Panaskan teflon, masukkan daging beserta bumbunya. Masak sampai air menyusut dan daging matang. Taburkan wijen dan daun bawang.', 'Angkat dan sajikan.']::text[] WHERE id = 168;

-- Resep ID: 170 - Kikil sapi bumbu urap
UPDATE public.recipes SET instructions = ARRAY['Tumis bumbu halus hingga harum, masukkan salam dan serai, tumis hingga bumbu matang.', 'Masukkan kikil sapi, beri gula dan garam, tuangi air dan biarkan mendidih hingga air sedikit menyusut. Tes rasanya.', 'Terakhir, masukkan kelapa yang sudah disangrai, aduk rata hingga kuah saat dan sedikit kering. Angkat dan sajikan.']::text[] WHERE id = 170;

-- Resep ID: 172 - Sup Iga dan Daging Sapi
UPDATE public.recipes SET instructions = ARRAY['Cuci bersih iga dan daging sapi, kemudian tiriskan. Jangan direndam.', 'Haluskan semua bumbu dengan menggunakan minyak.', 'Nyalakan api, tuang bumbu yang dihaluskan ke dalam wajan penggorengan. Aduk bumbu, ketika mulai tercium aroma bawang dan minyak mulai terlihat, masukkan rempah kayu manis, bunga lawang, pala, dan cengkeh.', 'Masak terus bumbu sampai benar-benar matang dan wangi. Masak bumbu dengan api kecil agar matang sempurna. Jika minyak sudah naik ke permukaan dan terpisah dari bumbu, serta wanginya benar-benar harum, matikan api dan sisihkan bumbu.', 'Rebus air secukupnya sesuai dengan banyaknya daging. Masukkan iga dan daging sapi, beri garam secukupnya dan 1 bungkus kaldu sapi bubuk agar daging tidak terasa hambar. Angkat dan buang lemak atau busa yang naik ke permukaan.', 'Rebus iga dan daging sampai setengah empuk.', 'Masukkan bumbu yang telah dimasak tadi ke dalam rebusan daging dan iga. Jika tidak ingin kuah terlalu berminyak, saring sedikit bumbu. Namun, bagi yang ingin memasukkan semua bumbu beserta minyaknya, boleh saja karena minyaknya sangat wangi rempah.', 'Masak kembali sup sampai daging dan iga empuk. Cicipi rasa kuah, tambahkan garam, merica bubuk, gula, sisa kaldu sapi bubuk, atau penyedap rasa (jika suka) sampai rasanya pas.', 'Masak sampai iga dan daging empuk.', 'Setelah daging empuk, beri irisan daun bawang pada kuah, aduk rata.', 'Setelah api dimatikan, beri taburan daun seledri, bawang merah goreng, dan bawang putih goreng yang dihancurkan.', 'Angkat dan hidangkan.', 'Siapkan pelengkapnya yaitu sambal dan jeruk nipis.']::text[] WHERE id = 172;

-- Resep ID: 173 - Beef Teriyaki ala-ala Hokben
UPDATE public.recipes SET instructions = ARRAY['Iris daging sapi tipis-tipis seukuran setelunjuk atau sesuai selera.', 'Haluskan bawang putih dan jahe, atau geprek lalu cincang halus. Iris bawang bombay dan potong cabe hijau berbentuk persegi. Balurkan bawang putih dan jahe ke daging sapi, tambahkan garam, merica, saus tiram, dan saus teriyaki. Masukkan ke dalam kulkas dan diamkan, bisa semalaman.', 'Tumis bawang putih dan jahe hingga wangi. Masukkan daging sapi, saus tiram, saus teriyaki, merica, garam, gula pasir, dan minyak wijen. Masak hingga daging berubah warna. Tambahkan air, masak hingga daging empuk. Jika suka kuah banyak, air bisa ditambah. Untuk versi yang direndam bumbu di kulkas, tumis daging sapi beserta bumbu rendaman, minyak wijen, dan gula pasir hingga berubah warna, lalu tambahkan air dan masak hingga daging empuk.', 'Setelah daging empuk, cek rasa. Masukkan cabe hijau dan bawang bombay, masak sebentar agar tetap segar.', 'Tambahkan larutan maizena yang sudah dicampur air, aduk hingga mengental, lalu matikan api.', 'Siap disajikan dengan nasi hangat.']::text[] WHERE id = 173;

-- Resep ID: 175 - Beef patty steak black pepper sauce
UPDATE public.recipes SET instructions = ARRAY['Panaskan 2 sendok makan minyak, tumis bawang bombay dan bawang putih cincang hingga harum, angkat.', 'Campurkan daging cincang dengan bawang bombay dan bawang putih tumis, tambahkan tepung panir, merica, dan garam secukupnya. Cetak adonan menjadi bulat menggunakan tangan.', 'Panaskan 2 sendok makan minyak, masak beef patty hingga matang di kedua sisi, tiriskan.', 'Panaskan 2 sendok makan minyak, tumis bawang bombay hingga harum. Tambahkan saus tiram, saus sambal, kecap, dan tepung maizena yang telah dilarutkan. Aduk hingga mengental.', 'Potong-potong kentang, kukus hingga empuk. Angkat, lumuri dengan tepung maizena, lalu goreng hingga kering. Tiriskan.', 'Sajikan beef patty dengan saus black pepper dan kentang goreng.']::text[] WHERE id = 175;

-- Resep ID: 176 - sayur sop
UPDATE public.recipes SET instructions = ARRAY['Potong-potong semua sayuran (wortel, kentang, buncis, kubis, daun bawang) dan sisihkan.', 'Haluskan bawang putih, merica, dan garam. Tumis bumbu halus dengan sedikit minyak hingga harum.', 'Didihkan air dalam panci. Masukkan makaroni, kentang, dan wortel, masak hingga setengah matang.', 'Masukkan bumbu yang sudah ditumis ke dalam panci. Tambahkan buncis dan daun bawang.', 'Bumbui dengan kaldu bubuk, gula, dan merica. Terakhir, masukkan kubis dan seledri. Masak sebentar hingga semua matang. Sajikan dengan taburan bawang goreng.']::text[] WHERE id = 176;

-- Resep ID: 177 - tumis kangkung
UPDATE public.recipes SET instructions = ARRAY['Petik daun dan batang muda kangkung, cuci bersih, dan tiriskan.', 'Panaskan minyak, tumis bawang putih dan bawang merah hingga harum. Masukkan irisan cabai, tumis sebentar.', 'Masukkan kangkung ke dalam wajan, aduk rata.', 'Tambahkan saus tiram, kecap manis, garam, dan merica. Tuang sedikit air.', 'Masak dengan api besar hingga kangkung layu tetapi tetap hijau segar. Angkat dan sajikan.']::text[] WHERE id = 177;

-- Resep ID: 178 - tumis sawi putih
UPDATE public.recipes SET instructions = ARRAY['Cuci bersih sawi putih, lalu potong-potong sesuai selera.', 'Panaskan minyak, tumis bawang putih dan bawang merah hingga harum.', 'Masukkan potongan sawi putih ke dalam tumisan.', 'Tambahkan saus tiram, garam, dan merica. Aduk hingga sawi layu.', 'Angkat dan sajikan selagi hangat.']::text[] WHERE id = 178;

-- Resep ID: 179 - tahu tempe goreng
UPDATE public.recipes SET instructions = ARRAY['Haluskan bawang putih, garam, dan penyedap (MSG).', 'Campur bumbu halus dengan air. Masukkan potongan tahu dan tempe, ratakan, dan diamkan selama 20 menit agar bumbu meresap.', 'Panaskan minyak. Goreng tahu dan tempe hingga matang dan berwarna kecokelatan.', 'Angkat dan tiriskan. Tahu tempe goreng siap disajikan.']::text[] WHERE id = 179;

-- Resep ID: 180 - perkedel kentang
UPDATE public.recipes SET instructions = ARRAY['Kupas dan potong kentang, lalu goreng hingga matang.', 'Haluskan kentang goreng selagi hangat.', 'Campurkan kentang halus dengan bumbu halus (bawang putih, merica), bawang goreng, daun bawang, seledri, dan kuning telur.', 'Bentuk adonan menjadi bulat pipih. Celupkan ke dalam kocokan putih telur, lalu goreng dalam minyak panas hingga kecokelatan.', 'Angkat, tiriskan, dan sajikan.']::text[] WHERE id = 180;

-- Resep ID: 181 - Capcay
UPDATE public.recipes SET instructions = ARRAY['Cuci bersih dan potong semua sayuran (wortel, kembang kol, brokoli, sawi, jamur, buncis, jagung muda).', 'Panaskan minyak, tumis bawang putih dan bawang bombay hingga harum.', 'Masukkan wortel dan sayuran lainnya yang lebih keras terlebih dahulu, masak hingga agak layu.', 'Tambahkan minyak wijen, saus tiram, kecap manis, kecap asin, garam, gula, kaldu, dan lada. Aduk rata.', 'Masukkan larutan tepung maizena untuk mengentalkan kuah. Masak hingga semua matang, koreksi rasa, dan sajikan.']::text[] WHERE id = 181;

-- Resep ID: 182 - tumis wortel dan buncis
UPDATE public.recipes SET instructions = ARRAY['Kupas dan cuci bersih wortel dan buncis, lalu potong-potong (wortel serong, buncis sekitar 3 cm).', 'Tumis bawang merah, bawang putih, dan cabai hingga harum.', 'Masukkan wortel dan buncis ke dalam tumisan, aduk-aduk hingga layu.', 'Tambahkan garam, gula, dan sedikit air jika perlu. Masak hingga sayuran matang, angkat, dan sajikan.']::text[] WHERE id = 182;

-- Resep ID: 183 - sayur asem
UPDATE public.recipes SET instructions = ARRAY['Potong sayuran seperti kacang panjang, jagung manis, dan labu siam.', 'Haluskan bumbu yang terdiri dari bawang merah, bawang putih, cabai, dan terasi.', 'Didihkan air dalam panci, lalu masukkan bumbu halus, lengkuas, dan daun salam.', 'Masukkan jagung dan sayuran yang lebih keras terlebih dahulu. Masak hingga setengah matang.', 'Masukkan sisa sayuran, tambahkan asam jawa, garam, dan gula. Masak hingga semua sayuran matang. Sajikan.']::text[] WHERE id = 183;

-- Resep ID: 184 - Ayam Kecap
UPDATE public.recipes SET instructions = ARRAY['Cuci bersih ayam, lalu lumuri dengan garam dan merica. Diamkan sekitar 15 menit.', 'Goreng ayam dalam minyak panas hingga bagian luarnya kecokelatan (setengah matang), lalu angkat dan tiriskan.', 'Panaskan sedikit minyak, tumis bawang putih, bawang merah, dan bawang bombay hingga harum dan layu.', 'Masukkan ayam yang sudah digoreng ke dalam tumisan. Tambahkan kecap manis, saus tiram, kecap asin, gula, garam, dan merica. Aduk rata.', 'Tuang air secukupnya, kecilkan api, dan masak hingga kuah menyusut dan bumbu meresap ke dalam daging ayam.']::text[] WHERE id = 184;

-- Resep ID: 185 - Ayam Laos
UPDATE public.recipes SET instructions = ARRAY['Haluskan bawang merah, bawang putih, kunyit, kemiri, jahe, laos, dan ketumbar dengan cara diblender atau diulek.', 'Tumis bumbu halus bersama serai dan daun salam hingga matang. Masukkan ayam, aduk hingga berubah warna.', 'Tambahkan air, lalu masak hingga ayam empuk dan air menyusut.', 'Angkat ayam, lalu goreng dalam minyak panas hingga kuning kecokelatan. Sisihkan.', 'Saring sisa bumbu ungkep, lalu goreng hingga kering dan berwarna kecokelatan. Taburkan di atas ayam goreng.']::text[] WHERE id = 185;

-- Resep ID: 186 - sayur bayam
UPDATE public.recipes SET instructions = ARRAY['Siangi bayam, cuci bersih, dan tiriskan.', 'Didihkan air dalam panci.', 'Masukkan irisan bawang merah, garam, dan gula ke dalam air mendidih.', 'Masukkan bayam, masak sebentar sekitar 2 menit hingga layu.', 'Angkat dan sajikan selagi hangat.']::text[] WHERE id = 186;

-- Resep ID: 187 - Soto Ayam
UPDATE public.recipes SET instructions = ARRAY['Rebus ayam dalam air hingga setengah matang. Angkat ayam, sisihkan kaldunya.', 'Haluskan bumbu (bawang merah, bawang putih, kemiri, kunyit, jahe), lalu tumis bersama serai, daun jeruk, daun salam, dan lengkuas hingga harum.', 'Masukkan bumbu tumis ke dalam kaldu ayam, lalu rebus ayam kembali hingga matang. Bumbui dengan garam, kaldu bubuk, dan merica.', 'Angkat ayam, biarkan dingin, lalu suwir-suwir dagingnya.', 'Tata soun, tauge, telur rebus, dan suwiran ayam di mangkuk. Siram dengan kuah panas, taburi bawang goreng dan seledri.']::text[] WHERE id = 187;

-- Resep ID: 188 - tumis tempe kecap dan buncis
UPDATE public.recipes SET instructions = ARRAY['Potong tempe memanjang, iris buncis.', 'Goreng tempe hingga setengah matang atau kecokelatan.', 'Tumis bawang merah, bawang putih, dan daun salam hingga wangi.', 'Masukkan buncis dan air, masak hingga buncis mulai layu.', 'Masukkan tempe, kecap manis, garam, dan kaldu bubuk. Masak hingga bumbu meresap dan air surut. Angkat dan sajikan.']::text[] WHERE id = 188;

-- Resep ID: 189 - Bakwan Goreng
UPDATE public.recipes SET instructions = ARRAY['Haluskan bawang putih, ketumbar, merica, garam, dan kaldu bubuk.', 'Campur tepung terigu dan tepung beras (masukkan tepung bumbu bakwan instan). Masukkan bumbu halus dan telur. Tuang air sedikit demi sedikit sambil diaduk hingga adonan licin.', 'Masukkan wortel, kol, tauge, dan daun bawang ke dalam adonan. Aduk rata.', 'Panaskan minyak dalam jumlah banyak. Ambil satu sendok sayur adonan, goreng dalam minyak panas hingga kuning keemasan dan renyah.', 'Angkat dan tiriskan di atas kertas penyerap minyak.']::text[] WHERE id = 189;

-- Resep ID: 190 - Ayam Goreng Krispi
UPDATE public.recipes SET instructions = ARRAY['Campurkan tepung serbaguna, tepung terigu, bubuk paprika, garam, dan merica dalam kantong plastik. Kocok hingga rata.', 'Masukkan ayam ke dalam tepung, lalu ke dalam susu cair, terakhir masukkan lagi ke dalam kantong plastik berisi tepung. Kocok hingga ayam terlapisi tepung rata.', 'Keluarkan ayam dan biarkan sejenak sebelum digoreng.', 'Goreng dalam minyak yang sangat panas. Setelah kecoklatan, kecilkan api dan masak sekitar 30 menit. Bolak-balik dengan api sedang hingga renyah dan kecoklatan.']::text[] WHERE id = 190;

-- Resep ID: 191 - Rawon
UPDATE public.recipes SET instructions = ARRAY['Pecahkan kluwek, ambil isinya, dan rendam dalam air hangat selama 15-20 menit.', 'Rebus daging sapi hingga setengah matang. Sisihkan kaldunya.', 'Haluskan bumbu (bawang merah, bawang putih, kunyit, kemiri, ketumbar) termasuk kluwek yang sudah direndam. Tumis bumbu halus dalam minyak panas hingga harum.', 'Masukkan daging, asam jawa, serai, lengkuas, daun bawang, dan daun jeruk ke dalam tumisan. Tuang kaldu sedikit demi sedikit sambil diaduk, masak hingga bumbu meresap dan daging empuk.']::text[] WHERE id = 191;

-- Resep ID: 192 - bakwan jagung
UPDATE public.recipes SET instructions = ARRAY['Pipil jagung manis, cuci bersih, dan tiriskan.', 'Campur jagung, tepung terigu, tepung beras, telur, daun bawang, dan bumbu (bawang putih, merica, garam). Aduk rata.', 'Tambahkan air sedikit demi sedikit sambil diaduk hingga adonan memiliki kekentalan yang pas.', 'Panaskan minyak. Ambil satu sendok adonan dan goreng dalam minyak panas hingga berwarna kuning keemasan.', 'Angkat, tiriskan, dan sajikan selagi hangat.']::text[] WHERE id = 192;

-- Resep ID: 193 - mendol tempe
UPDATE public.recipes SET instructions = ARRAY['Haluskan semua bumbu, kemudian tambahkan garam dan gula.', 'Ulek tempe lalu campur dengan bumbu, kemudian aduk hingga merata.', 'Bentuk tempe menjadi bulatan lonjong.', 'Panaskan minyak, kemudian goreng tempe dengan api kecil hingga berwarna kecoklatan.', 'Tiriskan, siap disajikan.']::text[] WHERE id = 193;

-- Resep ID: 194 - Ayam Bumbu Kuning
UPDATE public.recipes SET instructions = ARRAY['Lumuri ayam dengan air jeruk nipis, diamkan selama 15 menit untuk menghilangkan bau amis.', 'Blender atau ulek bawang merah, bawang putih, kemiri, kunyit, dan jahe hingga halus.', 'Panaskan minyak, tumis bumbu halus bersama daun salam dan serai hingga harum.', 'Masukkan potongan ayam ke dalam bumbu tumis, aduk hingga ayam berubah warna.', 'Tambahkan air, garam, dan gula. Masak dengan api kecil hingga ayam empuk dan bumbu meresap.']::text[] WHERE id = 194;

-- Resep ID: 195 - Rendang
UPDATE public.recipes SET instructions = ARRAY['Blender semua bumbu halus (bawang, cabai, kemiri, jahe, lengkuas, lada, ketumbar) hingga halus.', 'Panaskan minyak, tumis bumbu halus bersama serai, daun jeruk, dan daun salam hingga harum dan matang.', 'Masukkan potongan daging sapi, aduk hingga berubah warna.', 'Tambahkan santan, air, gula merah, dan garam. Masak dengan api besar hingga mendidih.', 'Kecilkan api dan lanjutkan memasak selama 2-3 jam hingga daging empuk dan kuah mengental.']::text[] WHERE id = 195;

-- Resep ID: 196 - Mie Goreng Jawa
UPDATE public.recipes SET instructions = ARRAY['Rebus mie hingga matang, angkat, dan tiriskan.', 'Tumis bawang putih dan bawang bombay hingga harum. Masukkan daging ayam, masak hingga berubah warna.', 'Tambahkan wortel, kol, dan daun bawang. Masak hingga layu.', 'Masukkan mie yang sudah direbus, kecap manis, air asam jawa, garam, dan merica. Aduk rata hingga semua tercampur.', 'Sajikan dengan taburan bawang goreng dan seledri.']::text[] WHERE id = 196;

-- Resep ID: 197 - Sambal Goreng Ati Ampela
UPDATE public.recipes SET instructions = ARRAY['Rebus ati ampela dengan daun salam hingga matang dan empuk.', 'Kupas dan potong dadu kentang, lalu goreng hingga matang.', 'Potong-potong ati ampela, lalu goreng sebentar. Sisihkan.', 'Haluskan bumbu (bawang, cabai, kemiri, jahe) lalu tumis dengan daun salam, daun jeruk, serai, dan lengkuas hingga harum.', 'Masukkan kentang dan ati ampela, tambahkan garam, gula, dan sedikit air. Masak hingga bumbu meresap.']::text[] WHERE id = 197;

-- Resep ID: 198 - Opor Ayam
UPDATE public.recipes SET instructions = ARRAY['Panaskan minyak, tumis bumbu halus (bawang, kemiri, kunyit, ketumbar, merica) bersama daun salam, lengkuas, jahe, dan serai hingga harum.', 'Tambahkan potongan ayam, aduk hingga berubah warna.', 'Tuangkan santan encer, bumbui dengan garam, merica, dan gula merah.', 'Masak hingga santan sedikit meresap ke dalam ayam.', 'Masukkan santan kental. Masak sambil diaduk perlahan hingga kuah mengental dan matang.']::text[] WHERE id = 198;

-- Resep ID: 199 - Gado-Gado
UPDATE public.recipes SET instructions = ARRAY['Rebus semua sayuran (kentang, kol, wortel, kacang panjang, tauge) hingga matang.', 'Goreng tahu dan tempe hingga matang.', 'Goreng kacang tanah, lalu haluskan dengan bawang putih, gula merah, dan daun jeruk.', 'Tambahkan air asam jawa dan kecap manis ke dalam bumbu kacang halus, aduk rata.', 'Tata sayuran, tahu, tempe, dan telur di piring. Siram dengan bumbu kacang dan taburi bawang goreng.']::text[] WHERE id = 199;

-- Resep ID: 200 - Tempe Mendoan
UPDATE public.recipes SET instructions = ARRAY['Iris tipis tempe.', 'Campur tepung serbaguna, tepung beras, irisan daun bawang, dan air. Aduk hingga adonan tidak terlalu kental atau encer.', 'Celupkan irisan tempe ke dalam adonan.', 'Goreng dalam minyak panas sebentar saja (tidak terlalu kering) hingga berwarna kuning keemasan.']::text[] WHERE id = 200;

-- Resep ID: 201 - balado telur dan tahu
UPDATE public.recipes SET instructions = ARRAY['Rebus telur hingga matang, lalu kupas. Goreng tahu hingga matang, sisihkan.', 'Rebus atau blender cabai merah, cabai rawit, bawang merah, dan bawang putih hingga halus.', 'Tumis bumbu halus bersama daun salam hingga matang dan harum.', 'Masukkan garam, kaldu, dan gula merah. Masukkan telur dan tahu, beri sedikit air. Masak hingga bumbu meresap dan minyak terangkat. Sajikan.']::text[] WHERE id = 201;

COMMIT;
